def top_k_elements(nums: list[int], k: int) -> list[int]:
    from collections import Counter
    count = Counter(nums)
    # Sort by count descending, then by first occurrence index ascending
    first_index = {}
    for i, num in enumerate(nums):
        if num not in first_index:
            first_index[num] = i
    unique = list(count.keys())
    unique.sort(key=lambda x: (-count[x], first_index[x]))
    return unique[:k]
