def count_subsequence_matches(text: str, sub: str) -> int:
    n = len(text)
    m = len(sub)
    if m == 0:
        return 1
    if n < m:
        return 0

    # dp[j] = number of ways to form sub[:j] as a subsequence of text processed so far
    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(n):
        ch = text[i]
        # iterate j from m-1 down to 0 to avoid using the same character multiple times
        for j in range(m - 1, -1, -1):
            if ch == sub[j]:
                dp[j + 1] += dp[j]

    return dp[m]
```

