def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        # Compute remainder in balanced ternary
        # We want remainder r in {-1, 0, 1} such that n = 3*q + r
        # r = n % 3, but adjusted to be in {-1, 0, 1}
        r = n % 3
        if r > 1:
            r -= 3
            n = (n - r) // 3
        else:
            n = (n - r) // 3
        digits.append(r)

    # Convert digits to characters
    result = []
    for d in reversed(digits):
        if d == 1:
            result.append('+')
        elif d == -1:
            result.append('-')
        else:
            result.append('0')

    return ''.join(result)
