def longest_consecutive_streak(items: list[int]) -> int:
    if not items:
        return 0
    unique = set(items)
    longest = 0
    for num in unique:
        if num - 1 not in unique:
            current = num
            while current + 1 in unique:
                current += 1
            streak_len = current - num + 1
            if streak_len > longest:
                longest = streak_len
    return longest
