def balanced_ternary_str(n: int) -> str:
    """
    Convert an integer to its balanced ternary representation.

    Balanced ternary uses digits -1, 0, 1, represented as '-', '0', '+'.
    """
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        n = n // 3
        if remainder == 0:
            digits.append('0')
        elif remainder == 1:
            digits.append('+')
        elif remainder == 2:
            digits.append('-')
            n += 1
        elif remainder == -1:
            digits.append('+')
            n -= 1
        elif remainder == -2:
            digits.append('-')
            n += 1

    return ''.join(reversed(digits))
