            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Now reconstruct the lexicographically smallest LCS
    # We need to be careful: when a[i] != b[j], we have two choices.
    # We want the lexicographically smallest result.

    # We'll use memoization to avoid recomputation.
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(i: int, j: int) -> str:
