            return ""

        if a[i] == b[j]:
            return a[i] + solve(i + 1, j + 1)
        else:
            # Choose the option that gives lexicographically smaller result
            # Option 1: skip a[i] -> solve(i+1, j)
            # Option 2: skip b[j] -> solve(i, j+1)
            # But we need to be careful: both options should lead to LCS of the same length
            # dp[i][j] = max(dp[i+1][j], dp[i][j+1])
            # If dp[i+1][j] > dp[i][j+1], we must take option 1
            # If dp[i][j+1] > dp[i+1][j], we must take option 2
            # If equal, we need to compare the actual strings

