def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    # Build adjacency list
    adj = {}
    for u, v, w in edges:
        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []
        adj[u].append((v, w))
        adj[v].append((u, w))

    if start not in adj:
        return None

    # Dijkstra's algorithm with tie-breaking by lexicographic path
    # State: (cost, path) where path is list of nodes
    # We want to find the minimum cost, and among those, the lexicographically smallest path

    import heapq

    # Priority queue: (cost, path)
    # But comparing paths directly in heap is expensive. Instead, we can use a different approach.
    # Let's use Dijkstra where we track the best (cost, path) for each node.

    # dist[node] = (cost, path) - the best route to node
    dist = {}

    # Initialize
    dist[start] = (0, [start])

    # Priority queue: (cost, path) - we need to compare by cost first, then by path lexicographically
    # Python's heapq can compare tuples, so (cost, path) will work if path is comparable
    # But path is a list of strings, which is comparable lexicographically

    heap = [(0, [start])]

    while heap:
        cost, path = heapq.heappop(heap)
        node = path[-1]

        # If we've already found a better or equal route to this node, skip
        if node in dist:
            best_cost, best_path = dist[node]
            if cost > best_cost:
                continue
            if cost == best_cost and path > best_path:
                continue

        # If we reached the goal, we can return
        if node == goal:
            return (cost, path)

        # Explore neighbors
        if node not in adj:
            continue

        for neighbor, w in adj[node]:
            new_cost = cost + w
            new_path = path + [neighbor]

            # Check if this is better than what we have for neighbor
            if neighbor not in dist:
                dist[neighbor] = (new_cost, new_path)
                heapq.heappush(heap, (new_cost, new_path))
            else:
                best_cost, best_path = dist[neighbor]
                if new_cost < best_cost:
                    dist[neighbor] = (new_cost, new_path)
                    heapq.heappush(heap, (new_cost, new_path))
                elif new_cost == best_cost and new_path < best_path:
                    dist[neighbor] = (new_cost, new_path)
                    heapq.heappush(heap, (new_cost, new_path))

    return None
