        return (0, [start])

    # Build adjacency list
    adj = {}
    for u, v, w in edges:
        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Dijkstra's algorithm with lexicographic tie-breaking
    # dist[node] = minimum cost to reach node
    # path[node] = lexicographically smallest path (as tuple of nodes) among min-cost paths
    import heapq

    # Initialize
    dist = {start: 0}
    path = {start: (start,)}

    # Priority queue: (cost, path_tuple, node)
    # We use path_tuple for lexicographic comparison
    heap = [(0, (start,), start)]

    while heap:
        cost, path_tuple, node = heapq.heappop(heap)

        # If we've reached the goal, we can return immediately
        # because Dijkstra guarantees the first time we pop a node, it has the minimum cost,
        # and among same-cost paths, the lexicographically smallest is popped first
        if node == goal:
            return (cost, list(path_tuple))

        # If this entry is stale (we've found a better cost or same cost with lex smaller path), skip
        if cost > dist.get(node, float('inf')):
            continue
        if cost == dist.get(node, float('inf')) and path_tuple > path.get(node, ()):
            continue

        # Explore neighbors
        if node not in adj:
            continue

        for neighbor, weight in adj[node]:
            new_cost = cost + weight
            new_path = path_tuple + (neighbor,)

            # Check if this is better than what we have for neighbor
            if neighbor not in dist:
                # First time reaching neighbor
                dist[neighbor] = new_cost
                path[neighbor] = new_path
                heapq.heappush(heap, (new_cost, new_path, neighbor))
            else:
                # Compare with existing best
                if new_cost < dist[neighbor]:
                    dist[neighbor] = new_cost
                    path[neighbor] = new_path
                    heapq.heappush(heap, (new_cost, new_path, neighbor))
                elif new_cost == dist[neighbor]:
                    # Same cost, check lexicographic order
                    if new_path < path[neighbor]:
                        path[neighbor] = new_path
                        heapq.heappush(heap, (new_cost, new_path, neighbor))

    # If goal was never reached
    if goal not in dist:
        return None

    # This should not be reached if goal is reachable, but just in case
    return (dist[goal], list(path[goal]))

