def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    # Build adjacency list and in-degree count
    adj = [[] for _ in range(n)]
    in_degree = [0] * n

    for a, b in pairs:
        if a == b:
            return []
        adj[a].append(b)
        in_degree[b] += 1

    # Use a min-heap to always pick the smallest available node
    import heapq
    heap = []
    for i in range(n):
        if in_degree[i] == 0:
            heapq.heappush(heap, i)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != n:
        return []

    return result
