def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    # Build adjacency list
    adj = {}
    for u, v, w in edges:
        if u not in adj:
            adj[u] = []
        if v not in adj:
            adj[v] = []
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Dijkstra with lexicographic tie-breaking
    # State: (cost, path)
    # We want to find the minimum cost, and among those, the lexicographically smallest path

    import heapq

    # dist[node] = (cost, path) for the best path to node
    # We use a priority queue with (cost, path) where path is compared lexicographically
    # But we need to be careful: we want to minimize cost first, then lexicographic path

    # Initialize
    dist = {start: (0, [start])}
    # Priority queue: (cost, path_tuple, path_list)
    # We use path as tuple for comparison in heap
    heap = [(0, tuple([start]), [start])]

    visited = set()

    while heap:
        cost, path_tuple, path = heapq.heappop(heap)

        if path[-1] in visited:
            continue
        visited.add(path[-1])

        if path[-1] == goal:
            return (cost, path)

        for neighbor, w in adj.get(path[-1], []):
            new_cost = cost + w
            new_path = path + [neighbor]
            new_path_tuple = tuple(new_path)

            if neighbor not in dist:
                dist[neighbor] = (new_cost, new_path)
                heapq.heappush(heap, (new_cost, new_path_tuple, new_path))
            else:
                old_cost, old_path = dist[neighbor]
                old_path_tuple = tuple(old_path)
                # Compare: first by cost, then by lexicographic path
                if (new_cost, new_path_tuple) < (old_cost, old_path_tuple):
                    dist[neighbor] = (new_cost, new_path)
                    heapq.heappush(heap, (new_cost, new_path_tuple, new_path))

    return None
