def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    # Build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)
    nodes = set()
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))
        nodes.add(u)
        nodes.add(v)

    if start not in nodes and start != goal:
        return None
    if goal not in nodes and goal != start:
        return None

    # Dijkstra with lexicographic tie-breaking
    # We want the minimum cost path, and among those, the lexicographically smallest path
    # Use a priority queue with (cost, path) where path is compared lexicographically
    import heapq

    # dist[node] = minimum cost to reach node
    # best_path[node] = lexicographically smallest path among those with minimum cost
    dist = {start: 0}
    best_path = {start: [start]}

    # Priority queue: (cost, path_tuple, node)
    # We use path as tuple for comparison
    heap = [(0, (start,), start)]

    while heap:
        cost, path_tuple, node = heapq.heappop(heap)

        # If we've already found a better or equal cost with lexicographically smaller path, skip
        if node in dist and (cost > dist[node] or (cost == dist[node] and path_tuple > tuple(best_path[node]))):
            continue

        if node == goal:
            return (cost, list(path_tuple))

        for neighbor, w in adj[node]:
            new_cost = cost + w
