def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    # Build adjacency list, deduplicating edges
    adj = [set() for _ in range(n)]
    for u, v in edges:
        if u != v:
            adj[u].add(v)
            adj[v].add(u)

    # BFS to find shortest distance and count paths
    from collections import deque

    dist = [-1] * n
    count = [0] * n
    dist[source] = 0
    count[source] = 1

    queue = deque([source])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                count[v] = count[u]
                queue.append(v)
            elif dist[v] == dist[u] + 1:
                count[v] += count[u]

    if dist[target] == -1:
        return 0
    return count[target]
