def evaluate_expression(expr: str) -> int:
    """
    Evaluate a mathematical expression string and return the result as an integer.
    Supports +, -, *, /, parentheses, and integer division.
    """
    # Remove whitespace
    expr = expr.replace(' ', '')

    def parse_expression(index: int) -> tuple:
        """Parse expression: handles + and -"""
        value, index = parse_term(index)
        while index < len(expr) and expr[index] in '+-':
            op = expr[index]
            index += 1
            right_value, index = parse_term(index)
            if op == '+':
                value += right_value
            else:
                value -= right_value
        return value, index

    def parse_term(index: int) -> tuple:
        """Parse term: handles * and /"""
        value, index = parse_factor(index)
        while index < len(expr) and expr[index] in '*/':
            op = expr[index]
            index += 1
            right_value, index = parse_factor(index)
            if op == '*':
                value *= right_value
            else:
                # Integer division
                if right_value == 0:
                    raise ZeroDivisionError("Division by zero")
                value = int(value / right_value)
        return value, index

    def parse_factor(index: int) -> tuple:
        """Parse factor: handles parentheses and numbers"""
        if index >= len(expr):
            raise ValueError("Unexpected end of expression")

        if expr[index] == '(':
            index += 1
            value, index = parse_expression(index)
            if index >= len(expr) or expr[index] != ')':
                raise ValueError("Missing closing parenthesis")
            index += 1
            return value, index

        # Parse number (possibly negative)
        if expr[index] == '-':
            index += 1
            value, index = parse_number(index)
            return -value, index

        return parse_number(index)

    def parse_number(index: int) -> tuple:
        """Parse a number"""
        start = index
        while index < len(expr) and expr[index].isdigit():
            index += 1
        if start == index:
            raise ValueError(f"Expected number at position {index}")
        return int(expr[start:index]), index

    result, _ = parse_expression(0)
    return result
