def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens: list[tuple[str, str]] = []
    i = 0
    n = len(source)
    two_char_ops = {"==", "!=", "<=", ">="}
    single_char_ops = {"+", "-", "*", "/", "<", ">", "=", "(", ")", ","}

    while i < n:
        ch = source[i]
        # Skip whitespace
        if ch in ' \t\n':
            i += 1
            continue

        # Try two-character operators first
        if i + 1 < n:
            two = source[i:i+2]
            if two in two_char_ops:
                tokens.append(("OP", two))
                i += 2
                continue

        # Try single character operators
        if ch in single_char_ops:
            tokens.append(("OP", ch))
            i += 1
            continue

        # Try NUMBER: longest run of digits, optionally followed by '.' and at least one digit
        if ch.isdigit():
            j = i
            while j < n and source[j].isdigit():
                j += 1
            # Check for optional decimal part
            if j < n and source[j] == '.':
                # Must have at least one digit after the dot
                if j + 1 < n and source[j+1].isdigit():
                    j += 1
                    while j < n and source[j].isdigit():
                        j += 1
                else:
                    # Dot not followed by digit - this is an invalid '.'
                    raise ValueError(f"Invalid character '.' at position {j}")
            tokens.append(("NUMBER", source[i:j]))
            i = j
            continue

        # Try NAME: longest run of letters, digits, underscores, starting with letter or underscore
        if ch.isalpha() or ch == '_':
            j = i
            while j < n and (source[j].isalnum() or source[j] == '_'):
                j += 1
            tokens.append(("NAME", source[i:j]))
            i = j
            continue

        # Any other character is invalid
        raise ValueError(f"Invalid character '{ch}' at position {i}")

    return tokens

