from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    if n == 0:
        return start

    # Parse the start date
    start_date = datetime.strptime(start, "%Y-%m-%d").date()

    # Convert holidays to a set of date objects for O(1) lookup
    holiday_set = set()
    for h in holidays:
        holiday_set.add(datetime.strptime(h, "%Y-%m-%d").date())

    def is_business_day(d: datetime.date) -> bool:
        # Monday=0, Tuesday=1, ..., Friday=4, Saturday=5, Sunday=6
        return d.weekday() < 5 and d not in holiday_set

    if n > 0:
        current = start_date
        count = 0
        while count < n:
            current += timedelta(days=1)
            if is_business_day(current):
                count += 1
        return current.strftime("%Y-%m-%d")
    else:
        # n is negative
        current = start_date
        count = 0
        target = -n
        while count < target:
            current -= timedelta(days=1)
            if is_business_day(current):
                count += 1
        return current.strftime("%Y-%m-%d")
