def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return abs(a)

    def lcm(a: int, b: int) -> int:
        return abs(a * b) // gcd(a, b)

    def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
        if b == 0:
            return (1, 0, a)
        x1, y1, g = extended_gcd(b, a % b)
        return (y1, x1 - (a // b) * y1, g)

    # Start with the first congruence
    r, m = congruences[0]
    r = r % m
    current_r = r
    current_m = m

    for r, m in congruences[1:]:
        r = r % m
        # Solve: current_r + current_m * t ≡ r (mod m)
        # i.e., current_m * t ≡ (r - current_r) (mod m)
        g = gcd(current_m, m)
        diff = r - current_r
        if diff % g != 0:
            return None

        # Divide by g
        cm_div = current_m // g
        m_div = m // g
        diff_div = diff // g

        # Solve cm_div * t ≡ diff_div (mod m_div)
        # Since gcd(cm_div, m_div) = 1, find inverse of cm_div mod m_div
        x, y, _ = extended_gcd(cm_div, m_div)
        t = (x * diff_div) % m_div

        # New solution: current_r + current_m * t
        new_r = current_r + current_m * t
        new_m = lcm(current_m, m)

        current_r = new_r % new_m
        current_m = new_m

    return (current_r, current_m)
