        while b:
            a, b = b, a % b
        return abs(a)

    def lcm(a: int, b: int) -> int:
        return abs(a * b) // gcd(a, b)

    def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = extended_gcd(b, a % b)
        return (g, y1, x1 - (a // b) * y1)

    def mod_inverse(a: int, m: int) -> int | None:
        g, x, _ = extended_gcd(a, m)
        if g != 1:
            return None
        return x % m

    # Start with the first congruence
    r, m = congruences[0]
    r = r % m
    x = r
    L = m

    for r, m in congruences[1:]:
        r = r % m
        # We need to solve: x + L * k ≡ r (mod m)
        # i.e., L * k ≡ r - x (mod m)
        g = gcd(L, m)
        if (r - x) % g != 0:
            return None

        # Divide everything by g
        L_div = L // g
        m_div = m // g
        rhs = (r - x) // g

        # Solve L_div * k ≡ rhs (mod m_div)
        # Since gcd(L_div, m_div) = 1, we can find inverse of L_div mod m_div
        inv = mod_inverse(L_div, m_div)
        if inv is None:
            return None
        k = (rhs * inv) % m_div

        # Update x and L
        x = x + L * k
        L = lcm(L, m)
        x = x % L

    return (x, L)
