def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    """
    Solve a system of simultaneous congruences using the Chinese Remainder Theorem.

    Args:
        congruences: A list of (remainder, modulus) pairs.

    Returns:
        A tuple (solution, lcm) where solution is the smallest non-negative solution
        and lcm is the least common multiple of all moduli, or None if no solution exists.
    """
    if not congruences:
        return (0, 1)

    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return abs(a)

    def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = extended_gcd(b, a % b)
        return (g, y1, x1 - (a // b) * y1)

    def lcm(a: int, b: int) -> int:
        return abs(a * b) // gcd(a, b)

    # Start with the first congruence
    x = congruences[0][0] % congruences[0][1]
    m = congruences[0][1]

    for r, mod in congruences[1:]:
        # Solve x + m*k ≡ r (mod mod)
        # m*k ≡ r - x (mod mod)
        diff = (r - x) % mod
        g = gcd(m, mod)

        if diff % g != 0:
            return None

        # Reduce the equation
        m_reduced = m // g
        mod_reduced = mod // g
        diff_reduced = diff // g

        # Find inverse of m_reduced mod mod_reduced
        inv, _, _ = extended_gcd(m_reduced, mod_reduced)
        inv = inv % mod_reduced

        k = (diff_reduced * inv) % mod_reduced

        # Update x and m
        x = (x + m * k) % (m * mod_reduced)
        m = m * mod_reduced

    x = x % m
    return (x, m)
