def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_cols = len(rows[0])

    # Calculate column widths
    col_widths = [0] * num_cols
    for row in rows:
        for i, cell in enumerate(row):
            col_widths[i] = max(col_widths[i], len(cell))

    # Format each row
    formatted_rows = []
    for row in rows:
        cells = []
        for i, cell in enumerate(row):
            width = col_widths[i]
            align = aligns[i]
            padding = width - len(cell)
            if align == 'l':
                formatted_cell = cell + ' ' * padding
            elif align == 'r':
                formatted_cell = ' ' * padding + cell
            elif align == 'c':
                left_pad = padding // 2
                right_pad = padding - left_pad
                formatted_cell = ' ' * left_pad + cell + ' ' * right_pad
            else:
                # Default to left alignment for unknown align characters
                formatted_cell = cell + ' ' * padding
            cells.append(formatted_cell)
        formatted_rows.append(' | '.join(cells))

    return '\n'.join(formatted_rows)
