from collections import deque

def min_slides(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])

    start = None
    end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if start is None or end is None:
        return -1

    if start == end:
        return 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def slide(r, c, dr, dc):
        nr, nc = r, c
        while 0 <= nr + dr < rows and 0 <= nc + dc < cols and grid[nr + dr][nc + dc] != '#':
            nr += dr
            nc += dc
        return nr, nc

    visited = [[False] * cols for _ in range(rows)]
    visited[start[0]][start[1]] = True

    queue = deque()
    queue.append((start[0], start[1], 0))

    while queue:
        r, c, dist = queue.popleft()

        for dr, dc in directions:
            nr, nc = slide(r, c, dr, dc)
            if (nr, nc) == (r, c):
                continue
            if not visited[nr][nc]:
                if (nr, nc) == end:
                    return dist + 1
                visited[nr][nc] = True
                queue.append((nr, nc, dist + 1))

    return -1
