def min_slides(grid: list[str]) -> int:
    if not grid:
        return -1

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    start = None
    end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if start is None or end is None:
        return -1

    from collections import deque

    def slide(r, c, dr, dc):
        """Slide from (r,c) in direction (dr,dc), return the stopping cell."""
        nr, nc = r + dr, c + dc
        # Check if first cell is valid and not a wall
        if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
            return None
        if grid[nr][nc] == '#':
            return None
        # Slide until we hit a wall or boundary
        while True:
            nnr, nnc = nr + dr, nc + dc
            if nnr < 0 or nnr >= rows or nnc < 0 or nnc >= cols:
                break
            if grid[nnr][nnc] == '#':
                break
            nr, nc = nnr, nnc
        return (nr, nc)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS
    visited = set()
    visited.add(start)
    queue = deque()
    queue.append((start, 0))

    while queue:
        (r, c), dist = queue.popleft()
        if (r, c) == end:
            return dist
        for dr, dc in directions:
            new_pos = slide(r, c, dr, dc)
            if new_pos is not None and new_pos not in visited:
                visited.add(new_pos)
                queue.append((new_pos, dist + 1))

    return -1
