def min_slides(grid: list[str]) -> int:
    if not grid:
        return -1

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Find start and end
    start = None
    end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if start is None or end is None:
        return -1

    # BFS
    from collections import deque

    # State: (row, col)
    # We need to track visited states. Since the puck slides until it hits a wall or boundary,
    # the state is just the position. But wait, is that sufficient?
    # In a sliding puzzle where you always slide to the end, the position uniquely determines
    # the next possible moves. So yes, position is the state.

    visited = set()
    visited.add(start)

    queue = deque()
    queue.append((start[0], start[1], 0))  # (row, col, moves)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    while queue:
        r, c, moves = queue.popleft()

        if (r, c) == end:
            return moves

        for dr, dc in directions:
            # Slide in direction (dr, dc)
            nr, nc = r + dr, c + dc

            # Check if the first step is valid (not wall, not out of bounds)
            if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
                continue
            if grid[nr][nc] == '#':
                continue

            # Slide until we hit a wall or boundary
            while True:
                # Check if next cell is valid
                next_r, next_c = nr + dr, nc + dc
                if next_r < 0 or next_r >= rows or next_c < 0 or next_c >= cols:
                    break
                if grid[next_r][next_c] == '#':
                    break
                nr, nc = next_r, next_c

            # (nr, nc) is where the puck stops
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, moves + 1))

    return -1
