def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)

    # Identity matrix
    def identity():
        return [[1 % mod if i == j else 0 for j in range(n)] for i in range(n)]

    # Matrix multiplication with modulo
    def mat_mult(A, B):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                aik = A[i][k]
                for j in range(n):
                    result[i][j] = (result[i][j] + aik * B[k][j]) % mod
        return result

    # Reduce matrix entries modulo mod
    def reduce_matrix(M):
        return [[(M[i][j] % mod + mod) % mod for j in range(n)] for i in range(n)]

    # Base case: exp == 0
    if exp == 0:
        return identity()

    # Reduce the base matrix
    base = reduce_matrix(matrix)

    # Result starts as identity
    result = identity()

    # Binary exponentiation
    while exp > 0:
        if exp & 1:
            result = mat_mult(result, base)
        base = mat_mult(base, base)
        exp >>= 1

    return result
