    i = 0
    n = len(encoded)
    result = []
    while i < n:
        # Parse a token
        if encoded[i] == '\\':
            # Backslash followed by any single character
            if i + 1 < n:
                char = encoded[i + 1]
                i += 2
            else:
                # Should not happen for well-formed input, but handle gracefully
                char = '\\'
                i += 1
        else:
            char = encoded[i]
            i += 1

