def tidy_punctuation(text: str) -> str:
    import re

    # Paso 1: sustituir secuencias de espacios en blanco por un solo espacio y eliminar espacios al principio y al final
    text = re.sub(r'\s+', ' ', text).strip()

    # Paso 2: eliminar cada espacio que va seguido directamente de uno de los caracteres , . ; : ! ?
    text = re.sub(r'\s(?=[,.:;!?])', '', text)

    # Paso 3: después de cada uno de esos seis caracteres que vaya seguido directamente de una letra, se inserta un único espacio
    text = re.sub(r'([,.:;!?])([a-zA-Z])', r'\1 \2', text)

    # Paso 4: el primer carácter de la cadena, y todo carácter que aparezca justo después de uno de . ! ? más un espacio, se convierte a mayúscula
    result = list(text)
    if result:
        if result[0].isalpha():
            result[0] = result[0].upper()

    # Convertir a mayúscula los caracteres justo después de . ! ? seguido de espacio
    for i in range(len(result) - 1):
        if i + 1 < len(result):
            # Verificar si result[i] es uno de . ! ? y result[i+1] es espacio
            if result[i] in '.!?' and i + 2 < len(result) and result[i + 1] == ' ':
                if result[i + 2].isalpha():
                    result[i + 2] = result[i + 2].upper()

    return ''.join(result)
