def identifier_to_snake(name: str) -> str:
    """
    Convert an identifier to snake_case.

    Splits the identifier into words and returns them in lower case,
    joined by single underscores.
    """
    if not name:
        return ""

    # First, split by underscores and hyphens
    parts = []
    current = []
    for char in name:
        if char in ('_', '-'):
            if current:
                parts.append(''.join(current))
                current = []
        else:
            current.append(char)
    if current:
        parts.append(''.join(current))

    # Now split each part into words based on the rules
    words = []
    for part in parts:
        if not part:
            continue
        words_in_part = []
        i = 0
        n = len(part)
        while i < n:
            # Start a new word at position i
            j = i
            while j < n:
                if j + 1 < n:
                    c1 = part[j]
                    c2 = part[j + 1]
                    # Check if we should split between j and j+1
                    should_split = False
                    # Between lower-case and upper-case
                    if c1.islower() and c2.isupper():
                        should_split = True
                    # Between letter and digit
                    elif c1.isalpha() and c2.isdigit():
                        should_split = True
                    # Between digit and letter
                    elif c1.isdigit() and c2.isalpha():
                        should_split = True
                    # Between two consecutive upper-case letters when the second is followed by a lower-case letter
                    elif c1.isupper() and c2.isupper() and j + 2 < n and part[j + 2].islower():
                        should_split = True

                    if should_split:
                        break
                j += 1
            words_in_part.append(part[i:j])
            i = j
        words.extend(words_in_part)

    # Filter out empty words and convert to lowercase
    words = [w.lower() for w in words if w]

    return '_'.join(words)
