def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Filter out empty ranges and clip to day
    clipped = []
    for start, end in busy:
        if start >= end:
            continue
        # Clip to day
        new_start = max(start, day_start)
        new_end = min(end, day_end)
        if new_start < new_end:
            clipped.append((new_start, new_end))

    if not clipped:
        if day_end - day_start >= min_len:
            return [(day_start, day_end)]
        return []

    # Sort by start time
    clipped.sort(key=lambda x: x[0])

    # Merge overlapping/touching intervals
    merged = []
    for start, end in clipped:
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    # Find free gaps
    result = []
    current = day_start
    for start, end in merged:
        if start > current:
            gap_len = start - current
            if gap_len >= min_len:
                result.append((current, start))
        current = max(current, end)

    # Check after last busy interval
    if current < day_end:
        gap_len = day_end - current
        if gap_len >= min_len:
            result.append((current, day_end))

    return result
