def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by decreasing profit, stable sort preserves original order for equal profits
    sorted_jobs = sorted(jobs, key=lambda x: -x[2])

    # Find the maximum deadline to determine the number of slots
    max_deadline = 0
    for _, deadline, _ in jobs:
        if deadline > max_deadline:
            max_deadline = deadline

    # If no jobs or all deadlines are below 1, return empty list
    if max_deadline < 1:
        return []

    # slots[i] stores the job name placed in slot i+1 (1-indexed), or None if free
    slots = [None] * (max_deadline + 1)  # index 0 unused, slots[1] to slots[max_deadline]

    for name, deadline, profit in sorted_jobs:
        if deadline < 1:
            continue
        # Find the highest-numbered free slot <= deadline
        placed = False
        for slot_num in range(min(deadline, max_deadline), 0, -1):
            if slots[slot_num] is None:
                slots[slot_num] = name
                placed = True
                break
        # If not placed, skip the job

    # Collect placed jobs in order of slot number
    result = []
    for i in range(1, max_deadline + 1):
        if slots[i] is not None:
            result.append(slots[i])

    return result
