def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    blocked_set = set()
    for r, c in blocked:
        if 0 <= r < n and 0 <= c < n:
            blocked_set.add((r, c))

    # Use backtracking with bitmasks for efficiency
    # col_mask: columns that are occupied
    # diag1_mask: diagonals (r - c + n - 1) that are occupied
    # diag2_mask: diagonals (r + c) that are occupied

    def backtrack(row: int, col_mask: int, diag1_mask: int, diag2_mask: int) -> int:
        if row == n:
            return 1

        count = 0
        for col in range(n):
            # Check if square is blocked
            if (row, col) in blocked_set:
                continue

            # Check if column is free
            if col_mask & (1 << col):
                continue

            # Check diagonals
            d1 = row - col + n - 1  # range: 0 to 2n-2
            d2 = row + col           # range: 0 to 2n-2

            if diag1_mask & (1 << d1):
                continue
            if diag2_mask & (1 << d2):
                continue

            count += backtrack(row + 1, col_mask | (1 << col), diag1_mask | (1 << d1), diag2_mask | (1 << d2))

        return count

    return backtrack(0, 0, 0, 0)
