def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    blocked_set = set(blocked)

    def is_safe(row: int, col: int) -> bool:
        if (row, col) in blocked_set:
            return False
        # Check row
        for c in range(n):
            if c != col and (row, c) not in blocked_set:
                return False
        # Check column
        for r in range(n):
            if r != row and (r, col) not in blocked_set:
                return False
        # Check diagonals
        for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
            r, c = row + dr, col + dc
            while 0 <= r < n and 0 <= c < n:
                if (r, c) not in blocked_set:
                    return False
                r += dr
                c += dc
        return True

    def backtrack(row: int, count: int) -> int:
        if count == n:
            return 1
        if row == n:
            return 0

        total = 0
        for col in range(n):
            if is_safe(row, col):
                total += backtrack(row + 1, count + 1)
        return total

    return backtrack(0, 0)
