                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            ip += 1
        elif op == "JMP":
            if len(parts) < 2:
                return None
            try:
                t = int(parts[1])
            except ValueError:
                return None
            if t < 0:
                return None
            ip = t
