def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Bases must be between 2 and 36")

    if number == "" or number == "-":
        raise ValueError("Invalid number")

    negative = False
    if number[0] == '-':
        negative = True
        number = number[1:]
        if number == "":
            raise ValueError("Invalid number")

    # Convert from_base to integer
    value = 0
    for ch in number:
        if ch.isdigit():
            digit = int(ch)
        elif ch.isalpha():
            digit = ord(ch.lower()) - ord('a') + 10
        else:
            raise ValueError(f"Invalid character '{ch}'")

        if digit >= from_base:
            raise ValueError(f"Digit '{ch}' is not valid in base {from_base}")

        value = value * from_base + digit

    # Convert integer to to_base
    if value == 0:
        return "0"

    digits = []
    while value > 0:
        remainder = value % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('a') + remainder - 10))
        value //= to_base

    result = ''.join(reversed(digits))
    if negative:
        result = '-' + result

    return result
