def convert_base(number: str, from_base: int, to_base: int) -> str:
    """
    Convert a number string from one base to another.

    Args:
        number: The number as a string in from_base
        from_base: The base of the input number (2-36)
        to_base: The base to convert to (2-36)

    Returns:
        The number as a string in to_base

    Raises:
        ValueError: If number is empty, only '-', or contains invalid digits
    """
    # Validate bases
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36")

    # Handle empty string
    if not number:
        raise ValueError("Number string is empty")

    # Handle negative sign
    negative = False
    if number[0] == '-':
        negative = True
        number = number[1:]

    # If after removing sign, string is empty
    if not number:
        raise ValueError("Number is only a minus sign")

    # Create digit mapping
    def char_to_value(c):
        c = c.lower()
        if '0' <= c <= '9':
            return ord(c) - ord('0')
        elif 'a' <= c <= 'z':
            return ord(c) - ord('a') + 10
        else:
            raise ValueError(f"Invalid character: {c}")

    # Convert from string to integer
    value = 0
    for c in number:
        v = char_to_value(c)
        if v >= from_base:
            raise ValueError(f"Digit {c} is not valid in base {from_base}")
        value = value * from_base + v

    # If value is zero, return "0"
    if value == 0:
        return "0"

    # Convert integer to string in to_base
    def value_to_char(v):
        if v < 10:
            return chr(ord('0') + v)
        else:
            return chr(ord('a') + v - 10)

    digits = []
    while value > 0:
        digits.append(value_to_char(value % to_base))
        value //= to_base

    # Reverse digits
    digits.reverse()
    result = ''.join(digits)

    # Add negative sign if needed
    if negative:
        result = '-' + result

    return result
