def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def count_set_bits_upto(n: int) -> int:
        """Count total set bits in all numbers from 0 to n inclusive."""
        if n < 0:
            return 0
        total = 0
        bit = 0
        while (1 << bit) <= n:
            cycle = 1 << (bit + 1)
            full_cycles = (n + 1) // cycle
            remainder = (n + 1) % cycle
            total += full_cycles * (1 << bit) + max(0, remainder - (1 << bit))
            bit += 1
        return total

    return count_set_bits_upto(hi) - count_set_bits_upto(lo - 1)
