def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Make a deep copy
    result = [row[:] for row in grid]

    rows = len(result)
    cols = len(result[0]) if rows > 0 else 0

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Use a queue to track cells that need to be checked
    from collections import deque
    queue = deque()

    # Initialize queue with all cells that have >= 4 grains
    for r in range(rows):
        for c in range(cols):
            if result[r][c] >= 4:
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        if result[r][c] >= 4:
            # Topple
            excess = result[r][c] // 4
            result[r][c] -= excess * 4
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    result[nr][nc] += excess
                    if result[nr][nc] >= 4:
                        queue.append((nr, nc))

    return result
