import os
import subprocess


def count_lines(path: str) -> int:
    """
    Count the number of lines in a file, equivalent to `wc -l`.

    Args:
        path: Path to an existing regular file.

    Returns:
        Number of newline characters in the file.

    Raises:
        ValueError: If path is not a regular file or does not exist.
        OSError: If there are permission issues or other OS-level errors.
    """
    # Validate that path is a string
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    # Resolve the path safely
    try:
        resolved_path = os.path.realpath(path)
    except (OSError, ValueError) as e:
        raise OSError(f"Invalid path: {e}") from e

    # Check if the file exists and is a regular file
    if not os.path.exists(resolved_path):
        raise ValueError(f"File does not exist: {path}")

    if not os.path.isfile(resolved_path):
        raise ValueError(f"Path is not a regular file: {path}")

    # Check if it's a regular file (not a symlink to something else, etc.)
    if not os.path.isfile(resolved_path):
        raise ValueError(f"Path is not a regular file: {path}")

    # Use wc -l command with subprocess
    # Use list form to avoid shell injection
    try:
        result = subprocess.run(
            ['wc', '-l', resolved_path],
            capture_output=True,
            text=True,
            check=True,
            timeout=30
        )
    except subprocess.CalledProcessError as e:
        raise OSError(f"wc command failed: {e.stderr.strip()}") from e
    except subprocess.TimeoutExpired as e:
        raise OSError("wc command timed out") from e
    except FileNotFoundError:
        raise OSError("wc command not found") from e
    except OSError as e:
        raise OSError(f"Error executing wc: {e}") from e

    # Parse the output: wc -l outputs "count filename"
    try:
        count_str = result.stdout.strip().split()[0]
        return int(count_str)
    except (ValueError, IndexError) as e:
        raise OSError(f"Failed to parse wc output: {result.stdout}") from e

