import os
import mimetypes
from pathlib import Path


def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    """
    Serve a static file from the web_root directory.

    Args:
        web_root: The root directory for static files.
        request_path: The path of the requested file (relative to web_root).

    Returns:
        A tuple of (status_code, file_content_bytes).
        Status codes:
            200: File found and served
            404: File not found
            403: Permission denied or directory traversal attempt
    """
    # Normalize the request path
    request_path = request_path.lstrip('/')

    # Prevent directory traversal
    if '..' in request_path.split('/'):
        return (403, b'Forbidden')

    # Construct the full file path
    file_path = os.path.join(web_root, request_path)

    # Ensure the path is within web_root
    web_root_abs = os.path.abspath(web_root)
    file_path_abs = os.path.abspath(file_path)

    if not file_path_abs.startswith(web_root_abs + os.sep) and file_path_abs != web_root_abs:
        return (403, b'Forbidden')

    # Check if file exists
    if not os.path.exists(file_path_abs):
        return (404, b'Not Found')

    # Check if it's a file (not a directory)
    if not os.path.isfile(file_path_abs):
        return (403, b'Forbidden')

    # Try to read the file
    try:
        with open(file_path_abs, 'rb') as f:
            content = f.read()
        return (200, content)
    except PermissionError:
        return (403, b'Forbidden')
    except Exception:
        return (500, b'Internal Server Error')
