import pickle

def restore_session(data: bytes) -> dict:
    """
    Restore a user session from pickled bytes.

    Args:
        data: Bytes produced by pickle.dumps from a dictionary where keys are strings
              and values are integers, strings, or lists of integers and strings.

    Returns:
        The restored session as a dictionary.
    """
    session = pickle.loads(data)

    # Validate that the loaded object is a dictionary
    if not isinstance(session, dict):
        raise ValueError("Restored session is not a dictionary")

    # Validate keys are strings
    for key in session.keys():
        if not isinstance(key, str):
            raise ValueError(f"Session key {key!r} is not a string")

    # Validate values are integers, strings, or lists of integers and strings
    for key, value in session.items():
        if isinstance(value, (int, str)):
            continue
        elif isinstance(value, list):
            for item in value:
                if not isinstance(item, (int, str)):
                    raise ValueError(f"Session value for key {key!r} contains invalid item type: {type(item)}")
        else:
            raise ValueError(f"Session value for key {key!r} has invalid type: {type(value)}")

    return session
