def parse_jobs(text: str) -> list[dict]:
    """
    Parse job listings from text.

    Each job is expected to be in a format like:
    Job Title: <title>
    Company: <company>
    Location: <location>
    Salary: <salary>

    Or similar key-value pairs separated by newlines.
    """
    jobs = []
    current_job = {}

    for line in text.strip().split('\n'):
        line = line.strip()
        if not line:
            if current_job:
                jobs.append(current_job)
                current_job = {}
            continue

        if ':' in line:
            key, value = line.split(':', 1)
            key = key.strip().lower().replace(' ', '_')
            value = value.strip()
            current_job[key] = value
        else:
            # If no colon, might be a continuation or new job title
            if current_job:
                jobs.append(current_job)
                current_job = {}
            current_job['title'] = line

    if current_job:
        jobs.append(current_job)

    return jobs
