import ast
import operator

def evaluate_formula(formula: str, x: float) -> float:
    """
    Evaluate a mathematical formula string with variable x.
    Supports: x, numbers, +, -, *, /, **, unary -, parentheses,
    and functions: sqrt, abs, sin, cos.
    Raises ValueError for invalid formulas or unknown names.
    Raises ZeroDivisionError for division by zero.
    """
    # Define allowed names and their values
    allowed_names = {
        'x': x,
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos,
    }

    # Define allowed operators
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    # Parse the formula
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        raise ValueError(f"Invalid formula syntax: {formula}")

    # Evaluate the AST
    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return float(node.value)
            else:
                raise ValueError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.Name):
            if node.id in allowed_names:
                return allowed_names[node.id]
            else:
                raise ValueError(f"Unknown name: {node.id}")
        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type not in allowed_operators:
                raise ValueError(f"Unsupported operator: {op_type.__name__}")
            return allowed_operators[op_type](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand)
            op_type = type(node.op)
            if op_type not in allowed_operators:
                raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
            return allowed_operators[op_type](operand)
        elif isinstance(node, ast.Call):
            # Only allow calls to allowed functions
            if not isinstance(node.func, ast.Name):
                raise ValueError("Only simple function calls are allowed")
            func_name = node.func.id
            if func_name not in allowed_names:
                raise ValueError(f"Unknown function: {func_name}")
            func = allowed_names[func_name]
            # Check that it's actually a function
            if not callable(func):
                raise ValueError(f"{func_name} is not a function")
