        if local[i] in separators and local[i+1] in separators:
            return False

    # Validate domain part
    if not domain:
        return False

    labels = domain.split('.')
    if len(labels) < 2:
        return False

    # Each label must be non-empty
    for label in labels:
        if not label:
            return False

    # Each label (except last) must be non-empty sequence of ASCII letters and digits
    for label in labels[:-1]:
        for ch in label:
            if not (ch.isascii() and (ch.isalpha() or ch.isdigit())):
                return False

    # Last label: at least two ASCII letters and nothing else
    last_label = labels[-1]
    if len(last_label) < 2:
        return False
    for ch in last_label:
        if not (ch.isascii() and ch.isalpha()):
