import math
import ast
import operator

def evaluate_formula(formula: str, x: float) -> float:
    """
    Safely evaluate a mathematical formula with variable x.

    Args:
        formula: A string containing a mathematical expression
        x: The value to substitute for x

    Returns:
        The result of evaluating the formula as a float

    Raises:
        ValueError: If the formula is invalid or contains disallowed elements
        ZeroDivisionError: If division by zero occurs
    """
    # Define allowed functions
    allowed_functions = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos,
    }

    # Define allowed operators
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    # Parse the formula
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid formula syntax: {e}")

    # Evaluate the AST
    def _eval_node(node):
        if isinstance(node, ast.Expression):
            return _eval_node(node.body)
        elif isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return float(node.value)
            else:
                raise ValueError(f"Unsupported constant type: {type(node.value)}")
        elif isinstance(node, ast.Name):
            if node.id == 'x':
                return x
            elif node.id in allowed_functions:
                raise ValueError(f"Function '{node.id}' must be called with an argument")
            else:
                raise ValueError(f"Unknown name: {node.id}")
        elif isinstance(node, ast.BinOp):
            left = _eval_node(node.left)
            right = _eval_node(node.right)
            op_type = type(node.op)
            if op_type not in allowed_operators:
                raise ValueError(f"Unsupported operator: {op_type.__name__}")
            return allowed_operators[op_type](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = _eval_node(node.operand)
            op_type = type(node.op)
            if op_type not in allowed_operators:
                raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
            return allowed_operators[op_type](operand)
        elif isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name):
                raise ValueError("Only simple function calls are allowed")
            func_name = node.func.id
            if func_name not in allowed_functions:
                raise ValueError(f"Unknown function: {func_name}")
            if len(node.args) != 1:
                raise ValueError(f"Function '{func_name}' must have exactly one argument")
            if node.keywords:
                raise ValueError(f"Function '{func_name}' does not accept keyword arguments")
            arg = _eval_node(node.args[0])
            return allowed_functions[func_name](arg)
        else:
            raise ValueError(f"Unsupported AST node type: {type(node).__name__}")

    result = _eval_node(tree)
    return float(result)
