import os

def hash_pin(pin: str) -> str:
    """Hash a PIN (4-6 digits) and return a string representation."""
    if not isinstance(pin, str) or not (4 <= len(pin) <= 6) or not pin.isdigit():
        raise ValueError("Invalid PIN: must be a string of 4 to 6 digits")

    # Use a random salt for each hash
    salt = os.urandom(16)
    # Use PBKDF2 for key derivation
    key = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    # Combine salt and key into a single string
    return salt.hex() + ':' + key.hex()

def check_pin(pin: str, stored: str) -> bool:
    """Check if a PIN matches a stored hash."""
    if not isinstance(pin, str) or not (4 <= len(pin) <= 6) or not pin.isdigit():
        return False

    if not isinstance(stored, str) or ':' not in stored:
        return False

    try:
        salt_hex, key_hex = stored.split(':', 1)
        salt = bytes.fromhex(salt_hex)
        expected_key = bytes.fromhex(key_hex)
    except (ValueError, TypeError):
        return False

    # Recompute the hash with the same salt
    key = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)

    # Use constant-time comparison to prevent timing attacks
    return hmac.compare_digest(key, expected_key)

