def is_local_redirect(target: str, host: str) -> bool:
    # Check for backslash, space, or control characters
    for ch in target:
        if ch == '\\' or ch == ' ' or ord(ch) < 32 or ord(ch) == 127:
            return False

    # Case 1: site-relative path
    if target.startswith('/'):
        if len(target) == 1:
            return True
        if target[1] != '/':
            return True
        return False

    # Case 2: http:// or https:// with matching host
    lower_target = target.lower()
    if lower_target.startswith('http://') or lower_target.startswith('https://'):
        # Extract the host part
        # Remove the scheme
        if lower_target.startswith('http://'):
            rest = target[7:]
        else:
            rest = target[8:]

        # The host is everything up to the first '/', '?', or '#'
        # But we need to exclude user-info and port
        # Find the end of the host part
        end = len(rest)
        for i, ch in enumerate(rest):
            if ch in ('/', '?', '#'):
                end = i
                break

        host_part = rest[:end]

        # Remove port if present
        if ':' in host_part:
            host_part = host_part.rsplit(':', 1)[0]

        # Remove user-info if present
        if '@' in host_part:
            host_part = host_part.rsplit('@', 1)[1]

        # Compare case-insensitively
        return host_part.lower() == host.lower()

    return False
