                if len(part) > 1 and part[0] == '0':
                    break
                if int(part) > 255:
                    break
            else:
                # Valid IPv4 format
                try:
                    ipv4 = ipaddress.IPv4Address(ip_str)
                    return _is_public_ipv4(ipv4)
                except (ipaddress.AddressValueError, ValueError):
                    return False
    except Exception:
        pass

