def render_report_header(template: str, report: dict) -> str:
    """Render a Jinja2 template with the report dict, converting values to str
    without escaping, and treating missing keys as empty strings."""
    # Create a custom environment with autoescape disabled
    env = jinja2.Environment(
        autoescape=False,
        undefined=jinja2.ChainableUndefined,
    )

    # Create a wrapper that converts values to str and handles missing keys
    class ReportWrapper:
        def __init__(self, data):
            self._data = data

        def __getattr__(self, name):
            if name.startswith('_'):
                raise AttributeError(name)
            if name in self._data:
                return str(self._data[name])
            return ''

        def __getitem__(self, key):
            if key in self._data:
                return str(self._data[key])
            return ''

    wrapper = ReportWrapper(report)
    tmpl = env.from_string(template)
    return tmpl.render(report=wrapper)
