from jinja2 import Environment, BaseLoader, StrictUndefined


def render_report_header(template: str, report: dict) -> str:
    """
    Render a Jinja2 template with a single variable 'report' containing the report dict.
    - Values are converted to str and inserted without escaping.
    - Missing keys in report are treated as empty string for {{ }} and False for {% if %}.
    - Supports conditional blocks like {% if report.key %}...{% endif %} (no else).
    - Spaces inside delimiters are optional.
    """
    # Create a custom environment
    env = Environment(loader=BaseLoader(), autoescape=False, undefined=StrictUndefined)

    # We need to handle missing keys gracefully.
    # Jinja2's default behavior for missing attributes on a dict is to raise UndefinedError.
    # We want missing keys to be treated as empty string for output and False for conditionals.

    # One approach: Pre-process the report dict to include all keys that might be referenced?
    # But we don't know all keys in advance.

    # Better approach: Use a custom Undefined class that returns empty string for str() and False for bool().

    class CustomUndefined:
        def __init__(self, hint=None):
            self.hint = hint

        def __str__(self):
            return ""

        def __bool__(self):
            return False

        def __getattr__(self, name):
            # If someone tries to access an attribute on the undefined, return another undefined
            return CustomUndefined()

        def __getitem__(self, key):
            return CustomUndefined()

        def __iter__(self):
            return iter([])

        def __len__(self):
            return 0

    env2 = Environment(loader=BaseLoader(), autoescape=False, undefined=CustomUndefined)

    # Compile the template
    try:
        tmpl = env2.from_string(template)
    except Exception as e:
        # If there's a syntax error, re-raise
        raise e

    # Render with the report dict
    result = tmpl.render(report=report)

    return result
