def render_greeting_card(template: str, recipient: str, sender: str) -> str:
    import re

    # Define the supported filters
    filters = {
        'upper': str.upper,
        'lower': str.lower,
        'capitalize': str.capitalize,
    }

    # Pattern to match {{ variable }} or {{ variable|filter }}
    # variable can be any word, filter is optional
    pattern = re.compile(r'\{\{\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*(?:\|\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*)?\}\}')

    def replace_match(match):
        var_name = match.group(1)
        filter_name = match.group(2)

        # Get the value based on variable name
        if var_name == 'recipient':
            value = recipient
        elif var_name == 'sender':
            value = sender
        else:
            # Unknown variable, return empty string
            return ''

        # Apply filter if specified
        if filter_name and filter_name in filters:
            value = filters[filter_name](value)
        elif filter_name:
            # Unknown filter, just return the value as is
            pass

        return value

    return pattern.sub(replace_match, template)
