def log_login_attempt(log_path: str, timestamp: str, username: str, success: bool) -> None:
    # Sanitize inputs to prevent log injection
    # Remove any newline characters and other control characters that could be used for log injection
    def sanitize(value: str) -> str:
        # Remove carriage returns, newlines, and other control characters
        return ''.join(ch for ch in value if ch.isprintable() and ch not in ('\r', '\n'))

    safe_timestamp = sanitize(timestamp)
    safe_username = sanitize(username)

    if success:
        line = f"{safe_timestamp} INFO login succeeded user={safe_username}\n"
    else:
        line = f"{safe_timestamp} WARNING login failed user={safe_username}\n"

    # Open file in append mode with UTF-8 encoding
    # Use 'a' mode to append, creating the file if it doesn't exist
    with open(log_path, 'a', encoding='utf-8') as f:
        f.write(line)

