def log_requests(log_path: str, requests: list[dict]) -> int:
    """
    Añade una línea por petición al final del archivo de texto en la ruta log_path.

    Args:
        log_path: Ruta al archivo de log
        requests: Lista de diccionarios con las entradas 'timestamp', 'ip', 'path' y 'user_agent'

    Returns:
        Número de líneas añadidas
    """
    # Validar que log_path es una cadena válida
    if not isinstance(log_path, str) or not log_path:
        raise ValueError("log_path debe ser una cadena no vacía")

    # Validar que requests es una lista
    if not isinstance(requests, list):
        raise TypeError("requests debe ser una lista")

    # Validar cada diccionario en requests
    required_keys = {'timestamp', 'ip', 'path', 'user_agent'}
    for i, req in enumerate(requests):
        if not isinstance(req, dict):
            raise TypeError(f"requests[{i}] debe ser un diccionario")
        missing_keys = required_keys - set(req.keys())
        if missing_keys:
            raise ValueError(f"requests[{i}] falta la(s) entrada(s): {missing_keys}")
        for key in required_keys:
            if not isinstance(req[key], str):
                raise TypeError(f"requests[{i}]['{key}'] debe ser una cadena")

    # Construir las líneas a escribir
    lines = []
    for req in requests:
        line = f"{req['timestamp']} {req['ip']} \"{req['path']}\" \"{req['user_agent']}\"\n"
        lines.append(line)

    # Escribir las líneas al archivo en modo append, codificación UTF-8
    with open(log_path, 'a', encoding='utf-8') as f:
        for line in lines:
            f.write(line)

    return len(requests)
