def parse_catalog(xml_text: str) -> list[dict]:
    """
    Parse an XML catalog string and return a list of book dictionaries.

    Args:
        xml_text: A string containing XML with root element 'catalog'

    Returns:
        A list of dictionaries, each with keys 'id', 'title', 'author'
    """
    if not xml_text or not xml_text.strip():
        return []

    try:
        # Use a safe parser that disables external entity resolution
        # to prevent XXE attacks
        parser = ET.XMLParser()
        root = ET.fromstring(xml_text, parser=parser)
    except ParseError:
        return []
    except Exception:
        return []

    # Check if root is 'catalog'
    if root.tag != 'catalog':
        return []

    books = []
    for book in root:
        # Only process direct children that are 'book' elements
        if book.tag != 'book':
            continue

        book_id = book.get('id', '')

        title = ''
        author = ''

        for child in book:
            if child.tag == 'title':
                title = child.text if child.text else ''
            elif child.tag == 'author':
                author = child.text if child.text else ''

        books.append({
            'id': book_id,
            'title': title,
            'author': author
        })

    return books

