    if not vals or len(vals) != len(weights):
        return 0.0

    total_weight = sum(weights)
    if total_weight == 0:
        return 0.0

    # Filter positive values and their corresponding weights
    positive_pairs = [(v, w) for v, w in zip(vals, weights) if v > 0]

    if not positive_pairs:
        return 0.0

    # Compute weighted harmonic mean: sum(weights) / sum(weights / vals)
    # But we need to use only the weights corresponding to positive vals
    # The formula for weighted harmonic mean is:
    # H = (sum of weights) / (sum of (weight_i / val_i))
    # where the sum is over all elements with positive vals

    sum_w = sum(w for _, w in positive_pairs)
    if sum_w == 0:
        return 0.0

    sum_w_over_v = sum(w / v for v, w in positive_pairs)
    if sum_w_over_v == 0:
        return 0.0

    result = sum_w / sum_w_over_v
    return round(result, 3)

