def count_subsequence_matches(text: str, sub: str) -> int:
    n = len(text)
    m = len(sub)
    if m == 0:
        return 1
    if n == 0:
        return 0

    # dp[j] = number of ways to form sub[:j] as a subsequence of text processed so far
    dp = [0] * (m + 1)
    dp[0] = 1

    for i in range(n):
        # iterate backwards to avoid using the same character multiple times
        for j in range(m, 0, -1):
            if text[i] == sub[j - 1]:
                dp[j] += dp[j - 1]

    return dp[m]
