def prefix_suffix_common(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0
    # Build the KMP failure function (prefix function)
    # pi[i] = length of the longest proper prefix of s[:i+1] that is also a suffix
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi[n - 1]

