def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    m, n = len(source), len(target)
    # dp[i][j] = min cost to convert source[:i] to target[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][0] = dp[i-1][0] + delete_cost
    for j in range(1, n + 1):
        dp[0][j] = dp[0][j-1] + insert_cost

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i-1] == target[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(
                    dp[i-1][j] + delete_cost,      # delete source[i-1]
                    dp[i][j-1] + insert_cost,      # insert target[j-1]
                    dp[i-1][j-1] + replace_cost    # replace source[i-1] with target[j-1]
                )

    return dp[m][n]
