    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Now reconstruct the lexicographically smallest LCS
    # We need to be careful: when a[i] != b[j], we should choose the path that leads to the lexicographically smallest result.
    # When a[i] == b[j], we have a choice: take this character or skip it. We should take it only if it leads to a lexicographically smaller result than skipping.

    # To do this efficiently, we can use memoization.
    # State: (i, j) -> the lexicographically smallest LCS of a[i:] and b[j:]
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(i, j):
        if i == n or j == m:
            return ""
        if a[i] == b[j]:
            # Option 1: take this character
            take = a[i] + solve(i + 1, j + 1)
            # Option 2: skip a[i]
            skip_a = solve(i + 1, j)
            # Option 3: skip b[j]
            skip_b = solve(i, j + 1)
            # We want the lexicographically smallest among all valid LCS
            # But note: take, skip_a, skip_b may have different lengths.
            # We only consider those with maximum length.
            # The maximum length is dp[i][j].
            max_len = dp[i][j]
            candidates = []
            if len(take) == max_len:
