def longest_bitonic_length(nums: list[int]) -> int:
    n = len(nums)
    if n == 0:
        return 0

    # inc[i] = length of longest strictly increasing subsequence ending at i
    # dec[i] = length of longest strictly decreasing subsequence starting at i
    inc = [1] * n
    dec = [1] * n

    # Compute inc
    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Compute dec (longest strictly decreasing subsequence starting at i)
    # This is equivalent to longest strictly increasing subsequence ending at i when traversing from right
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if nums[j] < nums[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    # The longest bitonic subsequence with peak at i has length inc[i] + dec[i] - 1
    # (subtract 1 because the peak is counted in both)
    return max(inc[i] + dec[i] - 1 for i in range(n))
