def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    from collections import defaultdict

    # Build adjacency list
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Tarjan's algorithm for finding bridges
    time = 0
    disc = [-1] * n
    low = [-1] * n
    bridges = []

    def dfs(u, parent):
        nonlocal time
        disc[u] = low[u] = time
        time += 1

        for v in adj[u]:
            if v == parent:
                continue
            if disc[v] == -1:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    a, b = (u, v) if u < v else (v, u)
                    bridges.append((a, b))
            else:
                low[u] = min(low[u], disc[v])

    for i in range(n):
        if disc[i] == -1:
