    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            i += 1

    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        tok = peek()
        pos[0] += 1
        return tok

    def parse_expr():
        # + and - (left to right)
        left = parse_term()
        while peek() and peek()[0] in ('+', '-'):
            op = consume()[0]
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        # * and / (left to right)
        left = parse_unary()
        while peek() and peek()[0] in ('*', '/'):
            op = consume()[0]
            right = parse_unary()
            if op == '*':
                left = left * right
            else:
                # Truncating division toward zero
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                # Python's // is floor division, we need truncation toward zero
                if (left >= 0 and right >= 0) or (left <= 0 and right <= 0):
                    left = left // right
                else:
                    left = -((-left) // right)
        return left

    def parse_unary():
        # unary minus
        if peek() and peek()[0] == '-':
            consume()
            return -parse_unary()
        return parse_power()

    def parse_power():
        # ^ is right-associative, higher precedence than unary minus
        base = parse_primary()
        if peek() and peek()[0] == '^':
            consume()
            exp = parse_power()  # right-associative
            return base ** exp
        return base

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        if tok[0] == 'num':
            consume()
            return tok[1]
