def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    from collections import OrderedDict

    if capacity == 0:
        results = []
        for op in operations:
            if op[0] == "get":
                results.append(None)
        return (results, [])

    cache = OrderedDict()
    results = []

    for op in operations:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                cache.move_to_end(key)
                cache[key] = value
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = value
        elif op[0] == "get":
            _, key = op
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(None)

    keys = list(cache.keys())
    return (results, keys)
