def run_stack_machine(program: list[str]) -> list[int]:
    stack: list[int] = []
    ip = 0
    executed = 0
    max_instructions = 1000

    while ip < len(program):
        if executed >= max_instructions:
            raise RuntimeError("Too many instructions executed")

        instruction = program[ip]
        parts = instruction.split()
        op = parts[0]

        if op == "PUSH":
            if len(parts) < 2:
                raise ValueError("Invalid PUSH instruction")
            try:
                n = int(parts[1])
            except ValueError:
                raise ValueError("Invalid PUSH value")
            stack.append(n)
            ip += 1
        elif op == "POP":
            if not stack:
                raise ValueError("Stack underflow on POP")
            stack.pop()
            ip += 1
        elif op == "DUP":
            if not stack:
                raise ValueError("Stack underflow on DUP")
            stack.append(stack[-1])
            ip += 1
        elif op == "SWAP":
            if len(stack) < 2:
                raise ValueError("Stack underflow on SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif op == "ADD":
            if len(stack) < 2:
                raise ValueError("Stack underflow on ADD")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            ip += 1
        elif op == "SUB":
            if len(stack) < 2:
                raise ValueError("Stack underflow on SUB")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1
        elif op == "MUL":
            if len(stack) < 2:
                raise ValueError("Stack underflow on MUL")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            ip += 1
        elif op == "JMP":
            if len(parts) < 2:
                raise ValueError("Invalid JMP instruction")
            try:
                t = int(parts[1])
            except ValueError:
                raise ValueError("Invalid JMP target")
            ip = t
        elif op == "JZ":
            if len(parts) < 2:
                raise ValueError("Invalid JZ instruction")
            if not stack:
                raise ValueError("Stack underflow on JZ")
            try:
                t = int(parts[1])
            except ValueError:
                raise ValueError("Invalid JZ target")
            val = stack.pop()
            if val == 0:
                ip = t
            else:
                ip += 1
        elif op == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {op}")

        executed += 1

    return stack
