def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_cols = len(rows[0])

    # Calculate column widths
    col_widths = [0] * num_cols
    for row in rows:
        for i, cell in enumerate(row):
            col_widths[i] = max(col_widths[i], len(cell))

    # Format each cell
    def format_cell(cell: str, width: int, align: str) -> str:
        pad = width - len(cell)
        if align == 'l':
            return cell + ' ' * pad
        elif align == 'r':
            return ' ' * pad + cell
        elif align == 'c':
            left_pad = pad // 2
            right_pad = pad - left_pad
            return ' ' * left_pad + cell + ' ' * right_pad
        else:
            return cell + ' ' * pad

    # Build formatted rows
    formatted_rows = []
    for row in rows:
        cells = []
        for i, cell in enumerate(row):
            align = aligns[i] if i < len(aligns) else 'l'
            cells.append(format_cell(cell, col_widths[i], align))
        formatted_rows.append(' | '.join(cells))

    return '\n'.join(formatted_rows)
