def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def gcd(a: int, b: int) -> int:
        a, b = abs(a), abs(b)
        while b:
            a, b = b, a % b
        return a

    def lcm(a: int, b: int) -> int:
        return abs(a * b) // gcd(a, b)

    def extended_gcd(a: int, b: int) -> tuple[int, int, int]:
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = extended_gcd(b, a % b)
        return (g, y1, x1 - (a // b) * y1)

    # Start with the first congruence
    r, m = congruences[0]
    r = r % m
    x = r
    L = m

    for r, m in congruences[1:]:
        r = r % m
        # Solve x + L * t ≡ r (mod m)
        # L * t ≡ r - x (mod m)
        g = gcd(L, m)
        if (r - x) % g != 0:
            return None

        # Divide by g
        L_div = L // g
        m_div = m // g
        rhs = (r - x) // g

        # Find inverse of L_div mod m_div
        # L_div * inv ≡ 1 (mod m_div)
        inv, _, _ = extended_gcd(L_div, m_div)
        inv = inv % m_div

        t = (rhs * inv) % m_div

        x = x + L * t
        L = lcm(L, m)
        x = x % L

    return (x, L)
