def min_slides(grid: list[str]) -> int:
    if not grid:
        return -1

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    start = None
    end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if start is None or end is None:
        return -1

    from collections import deque

    def slide(r, c, dr, dc):
        nr, nc = r + dr, c + dc
        while 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            nr += dr
            nc += dc
        # Step back to the last valid cell
        nr -= dr
        nc -= dc
        return nr, nc

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    visited = [[False] * cols for _ in range(rows)]
    queue = deque()
    queue.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True

    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == end:
            return dist
        for dr, dc in directions:
            nr, nc = slide(r, c, dr, dc)
            if (nr, nc) == (r, c):
                continue
            if not visited[nr][nc]:
                visited[nr][nc] = True
                queue.append((nr, nc, dist + 1))

    return -1
