    if not grid:
        return -1
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    start = None
    end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    from collections import deque

    def slide(r, c, dr, dc):
        """Slide in direction (dr, dc) until hitting wall or boundary.
        Returns the final position, or None if the first step is blocked."""
        nr, nc = r + dr, c + dc
        if nr < 0 or nr >= rows or nc < 0 or nc >= cols:
            return None
        if grid[nr][nc] == '#':
            return None
        # Continue sliding
        while True:
            nnr, nnc = nr + dr, nc + dc
            if nnr < 0 or nnr >= rows or nnc < 0 or nnc >= cols:
                break
            if grid[nnr][nnc] == '#':
                break
            nr, nc = nnr, nnc
        return (nr, nc)

    # BFS
    visited = set()
    visited.add(start)
    queue = deque()
    queue.append((start[0], start[1], 0))

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == end:
            return dist
        for dr, dc in directions:
            pos = slide(r, c, dr, dc)
            if pos is not None and pos not in visited:
                visited.add(pos)
                queue.append((pos[0], pos[1], dist + 1))

    return -1
