def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)

    # Handle mod == 1 case: all entries are 0
    if mod == 1:
        return [[0] * n for _ in range(n)]

    # Identity matrix
    def identity():
        return [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    # Matrix multiplication with modulo
    def mat_mult(A, B):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] != 0:
                    aik = A[i][k]
                    for j in range(n):
                        result[i][j] = (result[i][j] + aik * B[k][j]) % mod
        return result

    # Normalize matrix entries modulo mod
    def normalize(M):
        return [[(M[i][j] % mod + mod) % mod for j in range(n)] for i in range(n)]

    if exp == 0:
        return identity()

    # Binary exponentiation
    result = identity()
    base = normalize(matrix)

    while exp > 0:
        if exp % 2 == 1:
            result = mat_mult(result, base)
        base = mat_mult(base, base)
        exp //= 2

    return result
