def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    n = len(encoded)
    while i < n:
        # Determine the token character
        if encoded[i] == '\\':
            # Escaped character: next character is the literal
            if i + 1 >= n:
                break
            char = encoded[i + 1]
            i += 2
        else:
            char = encoded[i]
            i += 1

        # Check if followed by ~ and a number
        if i < n and encoded[i] == '~':
            i += 1  # skip ~
            # Read the number
            num_str = ''
            while i < n and encoded[i].isdigit():
                num_str += encoded[i]
                i += 1
            count = int(num_str) if num_str else 0
            result.append(char * count)
        else:
            result.append(char)

    return ''.join(result)
