    i = 0
    n = len(encoded)
    while i < n:
        if encoded[i] == '\\':
            # Backslash followed by a single character
            i += 1
            if i < n:
                char = encoded[i]
                i += 1
            else:
                char = '\\'
                continue
        else:
            char = encoded[i]
            i += 1

        # Check if followed by ~ and a number
        if i < n and encoded[i] == '~':
            i += 1
            # Read all consecutive digits
            num_str = ''
            while i < n and encoded[i].isdigit():
                num_str += encoded[i]
                i += 1
            count = int(num_str) if num_str else 0
            result.append(char * count)
        else:
            result.append(char)

    return ''.join(result)

