def expand_template(template: str, values: dict[str, str]) -> str:
    result = []
    i = 0
    n = len(template)

    while i < n:
        # Check for {{
        if i + 1 < n and template[i] == '{' and template[i + 1] == '{':
            result.append('{')
            i += 2
            continue

        # Check for }}
        if i + 1 < n and template[i] == '}' and template[i + 1] == '}':
            result.append('}')
            i += 2
            continue

        # Check for {
        if template[i] == '{':
            # Find the next }
            j = i + 1
            while j < n and template[j] != '}':
                j += 1

            if j < n:
                # Found a closing brace
                key = template[i + 1:j]
                if key in values:
                    result.append(values[key])
                    i = j + 1
                    continue
                else:
                    # Placeholder remains unchanged
                    result.append(template[i:j + 1])
                    i = j + 1
                    continue
            else:
                # No closing brace found, preserve as normal character
                result.append('{')
                i += 1
                continue

        # Check for standalone }
        if template[i] == '}':
            result.append('}')
            i += 1
            continue

        # Normal character
        result.append(template[i])
        i += 1

    return ''.join(result)
