def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Filter out empty ranges and clip to day boundaries
    clipped = []
    for start, end in busy:
        if start >= end:
            continue
        # Clip to day
        s = max(start, day_start)
        e = min(end, day_end)
        if s < e:
            clipped.append((s, e))

    if not clipped:
        if day_end - day_start >= min_len:
            return [(day_start, day_end)]
        return []

    # Sort by start time
    clipped.sort(key=lambda x: x[0])

    # Merge overlapping/adjacent intervals
    merged = []
    for s, e in clipped:
        if merged and s <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], e))
        else:
            merged.append((s, e))

    # Find gaps
    result = []
    prev_end = day_start
    for s, e in merged:
        if s > prev_end:
            gap_len = s - prev_end
            if gap_len >= min_len:
                result.append((prev_end, s))
        prev_end = max(prev_end, e)

    # Check gap after last busy interval
    if prev_end < day_end:
        gap_len = day_end - prev_end
        if gap_len >= min_len:
            result.append((prev_end, day_end))

    return result
