def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    if not results:
        return []

    # Dictionary to store team stats: {team: [points, goals_scored, goals_conceded]}
    teams = {}

    for home, away, home_goals, away_goals in results:
        # Initialize teams if not present
        if home not in teams:
            teams[home] = [0, 0, 0]
        if away not in teams:
            teams[away] = [0, 0, 0]

        # Update goals
        teams[home][1] += home_goals
        teams[home][2] += away_goals
        teams[away][1] += away_goals
        teams[away][2] += home_goals

        # Update points
        if home_goals > away_goals:
            teams[home][0] += 3
        elif home_goals < away_goals:
            teams[away][0] += 3
        else:
            teams[home][0] += 1
            teams[away][0] += 1

    # Build list of tuples (team, points, goal_difference, goals_scored)
    table = []
    for team, (points, goals_scored, goals_conceded) in teams.items():
        goal_difference = goals_scored - goals_conceded
        table.append((team, points, goal_difference, goals_scored))

    # Sort: points desc, goal_difference desc, goals_scored desc, team name asc
    table.sort(key=lambda x: (-x[1], -x[2], -x[3], x[0]))

    return table
