        # Update points
        if home_goals > away_goals:
            stats[home][0] += 3
        elif home_goals < away_goals:
            stats[away][0] += 3
        else:
            stats[home][0] += 1
            stats[away][0] += 1

    # Build list of tuples (team, points, goal_difference, goals_scored)
    table = []
    for team, (points, goals_scored, goals_conceded) in stats.items():
        goal_difference = goals_scored - goals_conceded
        table.append((team, points, goal_difference, goals_scored))

    # Sort by points desc, goal_difference desc, goals_scored desc, team asc
    table.sort(key=lambda x: (-x[1], -x[2], -x[3], x[0]))

