def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    for s in sizes:
        if s > capacity:
            raise ValueError(f"Element size {s} exceeds capacity {capacity}")

    # Sort in descending order
    sorted_sizes = sorted(sizes, reverse=True)

    bins = []  # list of lists, each bin contains the sizes placed in it
    bin_remaining = []  # remaining capacity for each bin

    for size in sorted_sizes:
        placed = False
        for i in range(len(bins)):
            if bin_remaining[i] >= size:
                bins[i].append(size)
                bin_remaining[i] -= size
                placed = True
                break
        if not placed:
            bins.append([size])
            bin_remaining.append(capacity - size)

    return bins
