def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock: dict[str, int] = {}
    pending: list[tuple[str, int]] = []  # (item, quantity) in order placed

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0

        if kind == 'receive':
            stock[item] += quantity
            # Fulfill pending orders for this item in order
            i = 0
            while i < len(pending):
                p_item, p_qty = pending[i]
                if p_item == item and stock[item] >= p_qty:
                    stock[item] -= p_qty
                    pending.pop(i)
                else:
                    i += 1
        elif kind == 'order':
            # Check if there's a pending order for the same item
            has_pending = any(p_item == item for p_item, _ in pending)
            if not has_pending and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                pending.append((item, quantity))

    return stock, pending
