def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    # Make a copy of balances
    final_balances = dict(balances)
    # Track frozen accounts
    frozen = set()
    failed = []

    for idx, op in enumerate(ops):
        if not isinstance(op, tuple) or len(op) == 0:
            failed.append(idx)
            continue

        op_type = op[0]

        if op_type == 'deposit':
            if len(op) != 3:
                failed.append(idx)
                continue
            _, account, amount = op
            if account not in final_balances:
                failed.append(idx)
                continue
            if not isinstance(amount, int) or amount <= 0:
                failed.append(idx)
                continue
            if account in frozen:
                failed.append(idx)
                continue
            final_balances[account] += amount

        elif op_type == 'withdraw':
            if len(op) != 3:
                failed.append(idx)
                continue
            _, account, amount = op
            if account not in final_balances:
                failed.append(idx)
                continue
            if not isinstance(amount, int) or amount <= 0:
                failed.append(idx)
                continue
            if account in frozen:
                failed.append(idx)
                continue
            if final_balances[account] - amount < 0:
                failed.append(idx)
                continue
            final_balances[account] -= amount

        elif op_type == 'transfer':
            if len(op) != 4:
                failed.append(idx)
                continue
            _, source, target, amount = op
            if source not in final_balances or target not in final_balances:
                failed.append(idx)
                continue
            if not isinstance(amount, int) or amount <= 0:
                failed.append(idx)
                continue
            if source in frozen or target in frozen:
                failed.append(idx)
                continue
            if source == target:
                failed.append(idx)
                continue
            # Fee is 2, deducted from source
            total_deduct = amount + 2
            if final_balances[source] - total_deduct < 0:
                failed.append(idx)
                continue
            final_balances[source] -= total_deduct
            final_balances[target] += amount

        elif op_type == 'freeze':
            if len(op) != 2:
                failed.append(idx)
                continue
            _, account = op
            if account not in final_balances:
                failed.append(idx)
                continue
            frozen.add(account)

        elif op_type == 'unfreeze':
            if len(op) != 2:
                failed.append(idx)
                continue
            _, account = op
            if account not in final_balances:
                failed.append(idx)
                continue
            frozen.discard(account)

        else:
            failed.append(idx)

    return (final_balances, failed)
