def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    from collections import defaultdict, deque

    stock: dict[str, int] = defaultdict(int)
    waiting: list[tuple[str, int]] = []
    waiting_by_item: dict[str, deque] = defaultdict(deque)

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
            # Fulfill waiting orders for this item
            while waiting_by_item[item] and stock[item] > 0:
                wait_item, wait_qty = waiting_by_item[item][0]
                if stock[item] >= wait_qty:
                    stock[item] -= wait_qty
                    waiting_by_item[item].popleft()
                    # Remove from waiting list
                    waiting.remove((wait_item, wait_qty))
                else:
                    break
        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))
                waiting_by_item[item].append((item, quantity))

    # Convert stock to regular dict, ensuring all items that appeared are included
    # Items with 0 stock are included
    result_stock = dict(stock)

    return (result_stock, waiting)
