def run_stack_program(program: list[str]) -> list[int] | None:
    stack: list[int] = []
    ip = 0
    steps = 0
    n = len(program)

    while ip < n:
        if steps > 1000:
            return None
        steps += 1

        if ip >= n:
            break

        instr = program[ip]
        parts = instr.split()
        op = parts[0]

        if op == "PUSH":
            if len(parts) < 2:
                return None
            try:
                val = int(parts[1])
            except ValueError:
                return None
            stack.append(val)
            ip += 1
        elif op == "POP":
            if not stack:
                return None
            stack.pop()
            ip += 1
        elif op == "DUP":
            if not stack:
                return None
            stack.append(stack[-1])
            ip += 1
        elif op == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif op == "ADD":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            ip += 1
        elif op == "SUB":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1
        elif op == "MUL":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            ip += 1
        elif op == "JMP":
            if len(parts) < 2:
                return None
            try:
                t = int(parts[1])
            except ValueError:
                return None
            if t < 0:
                return None
            ip = t
        elif op == "JZ":
            if len(parts) < 2:
                return None
            try:
                t = int(parts[1])
            except ValueError:
                return None
            if t < 0:
                return None
            if not stack:
                return None
            val = stack.pop()
            if val == 0:
                ip = t
            else:
                ip += 1
        else:
            return None

    if steps > 1000:
        return None

    return stack
