def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36 and 2 <= to_base <= 36):
        raise ValueError("Bases must be between 2 and 36")

    if not number:
        raise ValueError("Empty number")

    negative = False
    if number[0] == '-':
        negative = True
        number = number[1:]
        if not number:
            raise ValueError("Number contains only '-'")

    # Validate and convert to decimal
    decimal_value = 0
    for ch in number:
        if ch.isdigit():
            digit = int(ch)
        elif ch.isalpha():
            digit = ord(ch.lower()) - ord('a') + 10
        else:
            raise ValueError(f"Invalid character '{ch}' in number")

        if digit >= from_base:
            raise ValueError(f"Digit '{ch}' is not valid in base {from_base}")

        decimal_value = decimal_value * from_base + digit

    # Handle zero
    if decimal_value == 0:
        return "0"

    # Convert from decimal to target base
    digits = []
    while decimal_value > 0:
        remainder = decimal_value % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('a') + remainder - 10))
        decimal_value //= to_base

    result = ''.join(reversed(digits))
    if negative:
        result = '-' + result

    return result
