def shortest_path_one_break(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])

    start = end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # BFS with state: (row, col, used_break)
    # used_break: 0 or 1
    from collections import deque

    visited = [[[False, False] for _ in range(cols)] for _ in range(rows)]
    queue = deque()
    queue.append((start[0], start[1], 0, 0))  # row, col, used_break, distance
    visited[start[0]][start[1]][0] = True

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        r, c, used_break, dist = queue.popleft()

        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                cell = grid[nr][nc]
                if cell == '#':
                    if used_break == 0 and not visited[nr][nc][1]:
                        visited[nr][nc][1] = True
                        queue.append((nr, nc, 1, dist + 1))
                else:
                    # Empty cell, S, or E
                    if not visited[nr][nc][used_break]:
                        visited[nr][nc][used_break] = True
                        queue.append((nr, nc, used_break, dist + 1))

    return -1
