def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    # Create a copy of the grid
    result = [row[:] for row in grid]

    # Use a queue to track cells that need to be toppled
    from collections import deque
    queue = deque()

    # Initialize queue with all cells that have >= 4 grains
    for r in range(rows):
        for c in range(cols):
            if result[r][c] >= 4:
                queue.append((r, c))

    # Process topplings
    while queue:
        r, c = queue.popleft()
        if result[r][c] < 4:
            continue
        # Topple this cell
        grains = result[r][c] // 4
        result[r][c] -= grains * 4

        # Distribute to neighbors
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result[nr][nc] += grains
                if result[nr][nc] >= 4:
                    queue.append((nr, nc))

    return result
