def evaluate_expression(expression: str) -> float:
    """
    Evaluate an arithmetic expression with +, -, *, /, **, unary minus, parentheses.
    Raises ValueError for invalid expressions, ZeroDivisionError for division by zero.
    """
    import ast
    import operator

    # Define allowed operators
    allowed_ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        elif isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return float(node.value)
            else:
                raise ValueError(f"Unsupported constant: {node.value}")
        elif isinstance(node, ast.BinOp):
            left = _eval(node.left)
            right = _eval(node.right)
            op_type = type(node.op)
            if op_type not in allowed_ops:
                raise ValueError(f"Unsupported operator: {op_type.__name__}")
            return allowed_ops[op_type](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = _eval(node.operand)
            op_type = type(node.op)
            if op_type not in allowed_ops:
                raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
            return allowed_ops[op_type](operand)
        else:
            raise ValueError(f"Unsupported expression element: {type(node).__name__}")

    # Strip whitespace
    expr = expression.strip()
    if not expr:
        raise ValueError("Empty expression")

    # Try to parse
    try:
        tree = ast.parse(expr, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression: {e}")

    # Validate that only allowed nodes are present
    def _validate(node):
        if isinstance(node, ast.Expression):
            _validate(node.body)
        elif isinstance(node, ast.Constant):
            if not isinstance(node.value, (int, float)):
                raise ValueError(f"Unsupported constant type: {type(node.value).__name__}")
        elif isinstance(node, ast.BinOp):
            _validate(node.left)
            _validate(node.right)
            if type(node.op) not in allowed_ops:
                raise ValueError(f"Unsupported binary operator: {type(node.op).__name__}")
        elif isinstance(node, ast.UnaryOp):
            _validate(node.operand)
            if type(node.op) not in allowed_ops:
                raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")
        else:
            raise ValueError(f"Unsupported expression element: {type(node).__name__}")

    _validate(tree)

    return _eval(tree)
