def render_mail_merge(template: str, recipients: list[dict]) -> list[str]:
    from jinja2 import Environment, BaseLoader

    env = Environment(loader=BaseLoader(), autoescape=False)
    env.filters['str'] = lambda x: str(x)

    results = []
    for recipient in recipients:
        # Create a context where missing keys default to empty string
        # We need to handle missing variables by providing empty string
        # Jinja2's default filter can be used, but we need to set undefined to empty string
        # Use a custom undefined class
        from jinja2 import Undefined

        class EmptyUndefined(Undefined):
            def __str__(self):
                return ""
            def __iter__(self):
                return iter([])
            def __bool__(self):
                return False
            def __getattr__(self, name):
                return ""
            def __getitem__(self, name):
                return ""
            def __call__(self, *args, **kwargs):
                return ""

        env2 = Environment(loader=BaseLoader(), autoescape=False, undefined=EmptyUndefined)
        tmpl = env2.from_string(template)
        # Convert all values to str
        context = {k: str(v) for k, v in recipient.items()}
        results.append(tmpl.render(context))

    return results
