def render_report_header(template: str, report: dict) -> str:
    import re

    # We'll process the template by finding all {{ ... }} and {% ... %} blocks
    # and replacing them appropriately.

    # First, handle conditional blocks: {% if report.key %} ... {% endif %}
    # We need to handle nested or multiple conditionals. Let's use a simple approach:
    # Find all {% if report.key %} ... {% endif %} patterns.

    # Since the problem says "without an else part", we can handle simple if-endif blocks.
    # Let's process from innermost to outermost, or use a stack-based approach.

    # Actually, let's use a simpler regex-based approach that handles non-nested conditionals first,
    # then repeat until no more conditionals are found (to handle nesting).

    def get_report_value(key: str):
        """Get value from report dict, return None if key not present."""
        if key in report:
            return report[key]
        return None

    def is_truthy(value):
        """Check if value is truthy in Python sense."""
        if value is None:
            return False
        return bool(value)

    # Process conditionals: {% if report.key %} ... {% endif %}
    # We'll repeatedly find the innermost if-endif block and process it.

    # Pattern for if-endif block (non-greedy to find innermost)
    # The key can be any valid identifier
    if_pattern = re.compile(
        r'\{%-?\s*if\s+report\.(\w+)\s*-?%\}(.*?)\{%-?\s*endif\s*-?%\}',
        re.DOTALL
    )

    # Keep processing until no more if-endif blocks are found
    while True:
        match = if_pattern.search(template)
        if not match:
            break
        key = match.group(1)
        body = match.group(2)
        value = get_report_value(key)
        if is_truthy(value):
            replacement = body
        else:
            replacement = ''
        template = template[:match.start()] + replacement + template[match.end():]

    # Now handle variable substitutions: {{ report.key }}
    var_pattern = re.compile(
        r'\{\{-?\s*report\.(\w+)\s*-?\}\}'
    )

    def replace_var(match):
        key = match.group(1)
        value = get_report_value(key)
        if value is None:
            return ''
        return str(value)

    template = var_pattern.sub(replace_var, template)

    return template
