def word_frequency(text: str) -> dict[str, int]:
    """
    Return a dictionary mapping each word in the string `text` to the number of times it occurs.
    Words are the whitespace-separated pieces of `text`; they are compared in lowercase,
    and the dictionary keys are the lowercase words.
    An empty string gives an empty dictionary.
    """
    if not text:
        return {}

    words = text.lower().split()
    freq = {}
    for word in words:
        freq[word] = freq.get(word, 0) + 1
    return freq
