def merge_dicts(d1: dict, d2: dict) -> dict:
    """
    Merge two dictionaries with numeric values.
    For keys present in both, sum the values.
    For keys present in only one, keep the value.
    """
    result = {}
    all_keys = set(d1.keys()) | set(d2.keys())
    for key in all_keys:
        if key in d1 and key in d2:
            result[key] = d1[key] + d2[key]
        elif key in d1:
            result[key] = d1[key]
        else:
