    if n < 0:
        raise ValueError("n must be non-negative")
    row = [1]
    for i in range(1, n + 1):
        # Build the next row from the current row
        new_row = [1]
        for j in range(1, i):
            new_row.append(row[j - 1] + row[j])
        new_row.append(1)
        row = new_row
    return row

