def interleave_lists(a: list, b: list) -> list:
    result = []
    i, j = 0, 0
    while i < len(a) and j < len(b):
        result.append(a[i])
        result.append(b[j])
        i += 1
        j += 1
    if i < len(a):
        result.extend(a[i:])
    if j < len(b):
        result.extend(b[j:])
    return result

