def min_max_normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []

    min_val = min(nums)
    max_val = max(nums)

    if min_val == max_val:
        return [0.0] * len(nums)

    range_val = max_val - min_val
    result = []
    for num in nums:
        normalized = (num - min_val) / range_val
        result.append(round(normalized, 2))

    return result
