def weighted_harmonic_mean(vals: list[float], weights: list[float]) -> float:
    if not vals or len(vals) != len(weights):
        return 0.0

    total_weight = sum(weights)
    if total_weight == 0:
        return 0.0

    # Check if all vals are positive
    for v in vals:
        if v <= 0:
            return 0.0

    # Weighted harmonic mean = sum(weights) / sum(weights[i] / vals[i])
    denominator = sum(w / v for w, v in zip(weights, vals))
    if denominator == 0:
        return 0.0

    result = total_weight / denominator
    return round(result, 3)
