def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    n = len(intervals)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            s1, e1 = intervals[i]
            s2, e2 = intervals[j]
            # Two closed intervals [s1, e1] and [s2, e2] overlap if max(s1, s2) <= min(e1, e2)
            if max(s1, s2) <= min(e1, e2):
                count += 1
    return count
