def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        n = n // 3
        if remainder == 2:
            digits.append('-')
            n += 1
        elif remainder == -2:
            digits.append('+')
            n -= 1
        elif remainder == 1:
            digits.append('+')
        elif remainder == -1:
            digits.append('-')
        else:
            digits.append('0')

    return ''.join(reversed(digits))
