def longest_consecutive_streak(items: list[int]) -> int:
    if not items:
        return 0
    unique = set(items)
    longest = 0
    for num in unique:
        if num - 1 not in unique:
            current = num
            length = 1
            while current + 1 in unique:
                current += 1
                length += 1
            if length > longest:
                longest = length
    return longest
