def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Now reconstruct the lexicographically smallest LCS
    # We use memoization to avoid recomputation
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def solve(i: int, j: int) -> str:
        if i == n or j == m:
            return ""
        if a[i] == b[j]:
            return a[i] + solve(i + 1, j + 1)
        # We need to choose between a[i+1:] and b[j+1:]
        # We want the lexicographically smallest result
        # Option 1: skip a[i], take from a[i+1:]
        # Option 2: skip b[j], take from b[j+1:]
        # But we need to be careful: the LCS length is dp[i][j]
        # If dp[i+1][j] == dp[i][j], we can skip a[i]
        # If dp[i][j+1] == dp[i][j], we can skip b[j]

        # We want the lexicographically smallest string
        # Let's consider both options if they are valid
        candidates = []
        if dp[i + 1][j] == dp[i][j]:
            candidates.append(solve(i + 1, j))
        if dp[i][j + 1] == dp[i][j]:
            candidates.append(solve(i, j + 1))

        if not candidates:
            return ""

        return min(candidates)

    return solve(0, 0)
