    # Reconstruct the lexicographically smallest LCS
    # We use memoization to avoid recomputation
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def build(i: int, j: int) -> str:
        if i == n or j == m:
            return ""
        if a[i] == b[j]:
            return a[i] + build(i + 1, j + 1)
        # We need to choose between skipping a[i] or skipping b[j]
        # We want the lexicographically smallest result
        # Option 1: skip a[i] -> build(i+1, j)
        # Option 2: skip b[j] -> build(i, j+1)
        # But we must ensure we can still achieve the optimal length
        # dp[i][j] is the optimal length from (i,j)
        # If we skip a[i], the length we can get is dp[i+1][j]
        # If we skip b[j], the length we can get is dp[i][j+1]
        # We need to pick the option that gives the lexicographically smallest string
        # among those that achieve the optimal length dp[i][j]

        candidates = []
        if dp[i + 1][j] == dp[i][j]:
            candidates.append(build(i + 1, j))
        if dp[i][j + 1] == dp[i][j]:
            candidates.append(build(i, j + 1))

        if not candidates:
            return ""

        return min(candidates)

    return build(0, 0)
