def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens: list[tuple[str, str]] = []
    i = 0
    n = len(source)
    two_char_ops = {'==', '!=', '<=', '>='}
    single_char_ops = {'+', '-', '*', '/', '<', '>', '=', '(', ')', ','}

    while i < n:
        ch = source[i]
        # Skip whitespace
        if ch in ' \t\n':
            i += 1
            continue

        # Try two-character operators first
        if i + 1 < n:
            two = source[i:i+2]
            if two in two_char_ops:
                tokens.append(('OP', two))
                i += 2
                continue

        # Try single-character operators
        if ch in single_char_ops:
            tokens.append(('OP', ch))
            i += 1
            continue

        # Try NUMBER: maximal run of ASCII digits, optionally followed by one '.' and at least one more digit
        if ch.isdigit() and ch.isascii():
            j = i
            while j < n and source[j].isdigit() and source[j].isascii():
                j += 1
            # Check for optional decimal part
            if j < n and source[j] == '.':
                # Must have at least one digit after the dot
                if j + 1 < n and source[j+1].isdigit() and source[j+1].isascii():
                    j += 1
                    while j < n and source[j].isdigit() and source[j].isascii():
                        j += 1
            tokens.append(('NUMBER', source[i:j]))
            i = j
            continue

        # Try NAME: maximal run of ASCII letters, digits and underscores that starts with a letter or underscore
        if (ch.isalpha() and ch.isascii()) or ch == '_':
            j = i
            while j < n and ((source[j].isalnum() and source[j].isascii()) or source[j] == '_'):
                j += 1
            tokens.append(('NAME', source[i:j]))
            i = j
            continue

        # Any other character is invalid
        raise ValueError(f"Unexpected character: {ch!r}")

    return tokens

from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    if n == 0:
        return start

    start_date = datetime.strptime(start, "%Y-%m-%d").date()
    holiday_set = set(holidays)

    step = 1 if n > 0 else -1
    remaining = abs(n)
    current = start_date

    while remaining > 0:
        current += timedelta(days=step)
        # Check if current is a business day
        if current.weekday() < 5 and current.strftime("%Y-%m-%d") not in holiday_set:
            remaining -= 1

    return current.strftime("%Y-%m-%d")

