def run_stack_machine(program: list[str]) -> list[int]:
    stack: list[int] = []
    ip = 0
    executed = 0
    max_instructions = 1000

    while ip < len(program):
        if executed >= max_instructions:
            raise RuntimeError("Too many instructions executed")
        executed += 1

        instruction = program[ip]
        parts = instruction.split()
        op = parts[0]

        if op == "PUSH":
            if len(parts) != 2:
                raise ValueError(f"Invalid PUSH instruction: {instruction}")
            try:
                n = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid integer in PUSH instruction: {instruction}")
            stack.append(n)
            ip += 1

        elif op == "POP":
            if len(stack) < 1:
                raise ValueError("Stack underflow on POP")
            stack.pop()
            ip += 1

        elif op == "DUP":
            if len(stack) < 1:
                raise ValueError("Stack underflow on DUP")
            stack.append(stack[-1])
            ip += 1

        elif op == "SWAP":
            if len(stack) < 2:
                raise ValueError("Stack underflow on SWAP")
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1

        elif op == "ADD":
            if len(stack) < 2:
                raise ValueError("Stack underflow on ADD")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
            ip += 1

        elif op == "SUB":
            if len(stack) < 2:
                raise ValueError("Stack underflow on SUB")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
            ip += 1

        elif op == "MUL":
            if len(stack) < 2:
                raise ValueError("Stack underflow on MUL")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
            ip += 1

        elif op == "JMP":
            if len(parts) != 2:
                raise ValueError(f"Invalid JMP instruction: {instruction}")
            try:
                t = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid integer in JMP instruction: {instruction}")
            ip = t

        elif op == "JZ":
            if len(parts) != 2:
                raise ValueError(f"Invalid JZ instruction: {instruction}")
            try:
                t = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid integer in JZ instruction: {instruction}")
            if len(stack) < 1:
                raise ValueError("Stack underflow on JZ")
            val = stack.pop()
            if val == 0:
                ip = t
            else:
                ip += 1

        elif op == "HALT":
            break

        else:
            raise ValueError(f"Unknown instruction: {instruction}")

    return stack
