def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    n = len(matrix)

    # Identity matrix
    def identity():
        return [[1 % mod if mod != 0 else 0] * n for _ in range(n)]

    # Matrix multiplication with mod
    def mat_mult(A, B):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                aik = A[i][k]
                for j in range(n):
                    result[i][j] = (result[i][j] + aik * B[k][j]) % mod
        return result

    # Normalize matrix entries
    norm_matrix = [[x % mod for x in row] for row in matrix]

    if exp == 0:
        return identity()

    # Binary exponentiation
    result = identity()
    base = norm_matrix

    while exp > 0:
        if exp & 1:
            result = mat_mult(result, base)
        base = mat_mult(base, base)
        exp >>= 1

