    i = 0
    n = len(encoded)
    result = []
    while i < n:
        # Parse token
        if encoded[i] == '\\':
            # Escaped character: next char is the literal
            char = encoded[i + 1]
            i += 2
        else:
            char = encoded[i]
            i += 1

        # Check for ~ and number
        if i < n and encoded[i] == '~':
            i += 1
