def tidy_punctuation(text: str) -> str:
    import re

    # Step 1: collapse whitespace runs to single space, strip
    text = re.sub(r'\s+', ' ', text).strip()

    # Step 2: remove space directly before , . ; : ! ?
    text = re.sub(r' (?=[,.:;!?])', '', text)

    # Step 3: after each of , . ; : ! ? directly followed by a letter, insert a space
    text = re.sub(r'([,.:;!?])([A-Za-z])', r'\1 \2', text)

    # Step 4: capitalize first char and chars after . ! ? + space
    if not text:
        return text

    result = list(text)
    # capitalize first char
    if result[0].isalpha():
        result[0] = result[0].upper()

    # capitalize chars after . ! ? + space
    i = 0
    while i < len(result):
        if i + 3 < len(result):
            if result[i] in '.!?' and result[i+1] == ' ' and result[i+2].isalpha():
                result[i+2] = result[i+2].upper()
        i += 1

    return ''.join(result)

