def identifier_to_snake(name: str) -> str:
    if not name:
        return ""

    # Split by underscores and hyphens, ignoring empty parts
    parts = []
    current = []
    for ch in name:
        if ch in ('_', '-'):
            if current:
                parts.append(''.join(current))
                current = []
        else:
            current.append(ch)
    if current:
        parts.append(''.join(current))

    if not parts:
        return ""

    # Now split each part into words based on the rules
    words = []
    for part in parts:
        if not part:
            continue
        words_in_part = []
        i = 0
        n = len(part)
        start = 0
        while i < n:
            if i + 1 < n:
                c1 = part[i]
                c2 = part[i + 1]
                # Check for word boundaries
                boundary = False
                # lowercase followed by uppercase
                if c1.islower() and c2.isupper():
                    boundary = True
                # letter followed by digit
                if c1.isalpha() and c2.isdigit():
                    boundary = True
                # digit followed by letter
                if c1.isdigit() and c2.isalpha():
                    boundary = True
                # two consecutive uppercase, where the second is followed by lowercase
                if c1.isupper() and c2.isupper() and i + 2 < n and part[i + 2].islower():
                    boundary = True

                if boundary:
                    words_in_part.append(part[start:i + 1])
                    start = i + 1
            i += 1
        words_in_part.append(part[start:])
        words.extend(words_in_part)

    # Filter out empty words
    words = [w for w in words if w]

    if not words:
        return ""

    return '_'.join(w.lower() for w in words)
