def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36")

    if number == "" or number == "-":
        raise ValueError("Invalid number")

    # Handle negative sign
    negative = False
    if number[0] == '-':
        negative = True
        number = number[1:]
        if number == "":
            raise ValueError("Invalid number")

    # Validate and convert to integer
    value = 0
    for ch in number:
        c = ch.lower()
        if c.isdigit():
            digit = int(c)
        elif c.isalpha():
            digit = ord(c) - ord('a') + 10
        else:
            raise ValueError(f"Invalid character '{ch}' for base {from_base}")

        if digit >= from_base:
            raise ValueError(f"Digit '{ch}' is not valid in base {from_base}")

        value = value * from_base + digit

    # If value is zero, return "0"
    if value == 0:
        return "0"

    # Convert to target base
    digits = []
    while value > 0:
        remainder = value % to_base
        if remainder < 10:
            digits.append(str(remainder))
        else:
            digits.append(chr(ord('a') + remainder - 10))
        value //= to_base

    result = ''.join(reversed(digits))

    if negative:
        result = '-' + result

    return result
