def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Create a deep copy of the grid
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    new_grid = [[grid[r][c] for c in range(cols)] for r in range(rows)]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Use a queue to track cells that need to be checked
    from collections import deque
    queue = deque()

    # Initialize queue with all cells that have >= 4 grains
    for r in range(rows):
        for c in range(cols):
            if new_grid[r][c] >= 4:
                queue.append((r, c))

    # Process until queue is empty
    while queue:
        r, c = queue.popleft()
        if new_grid[r][c] >= 4:
            # Topple this cell
            new_grid[r][c] -= 4
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    new_grid[nr][nc] += 1
                    if new_grid[nr][nc] >= 4:
                        queue.append((nr, nc))

    return new_grid
