def shortest_path_one_break(grid: list[str]) -> int:
    if not grid:
        return -1

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    start = None
    end = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if start is None or end is None:
        return -1

    # BFS with state (r, c, used_break)
    # used_break: 0 or 1, whether we've used the one wall break
    from collections import deque

    # dist[r][c][used_break] = minimum steps to reach (r,c) with used_break breaks used
    dist = [[[float('inf')] * 2 for _ in range(cols)] for _ in range(rows)]

    dist[start[0]][start[1]][0] = 0
    dist[start[0]][start[1]][1] = 0  # Actually, we can't have used a break at start unless start is a wall, but S is not a wall

    q = deque()
    q.append((start[0], start[1], 0))

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while q:
        r, c, used = q.popleft()
        current_dist = dist[r][c][used]

        if (r, c) == end:
            return current_dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                cell = grid[nr][nc]
                if cell == '#':
                    # Wall: can only enter if we haven't used a break yet
                    if used == 0:
                        new_used = 1
                        new_dist = current_dist + 1
                        if new_dist < dist[nr][nc][new_used]:
                            dist[nr][nc][new_used] = new_dist
                            q.append((nr, nc, new_used))
                else:
                    # Empty cell or S or E
                    new_used = used
                    new_dist = current_dist + 1
                    if new_dist < dist[nr][nc][new_used]:
                        dist[nr][nc][new_used] = new_dist
                        q.append((nr, nc, new_used))

    # Check if end is reachable with either 0 or 1 break used
    result = min(dist[end[0]][end[1]][0], dist[end[0]][end[1]][1])
    return result if result != float('inf') else -1
