import os

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    # Normalize the request path
    # request_path starts with '/' and is URL-decoded
    # '/' means index.html
    # '/css/site.css' means css/site.css

    # Remove leading slash
    rel_path = request_path.lstrip('/')

    # If the path is empty, it means root, so use index.html
    if rel_path == '':
        rel_path = 'index.html'

    # Join with web_root
    full_path = os.path.join(web_root, rel_path)

    # Check if it's a regular file
    if os.path.isfile(full_path):
        try:
            with open(full_path, 'rb') as f:
                body = f.read()
            return (200, body)
        except (IOError, OSError):
            return (404, b"Not Found")
    else:
        return (404, b"Not Found")
