def restore_session(data: bytes) -> dict:
    """
    Restore a user session from the bytes `data` and return it as a dictionary.

    The bytes were produced by the application's session store with `pickle.dumps`
    from a dictionary whose keys are strings and whose values are integers, strings,
    or lists of integers and strings.

    Args:
        data: The pickled bytes representing the session.

    Returns:
        A dictionary representing the restored session.
    """
    import pickle

    session = pickle.loads(data)

    # Validate that the restored data is a dictionary
    if not isinstance(session, dict):
        raise ValueError("Restored session data is not a dictionary")

    # Validate keys are strings
    for key in session.keys():
        if not isinstance(key, str):
            raise ValueError(f"Session key {key!r} is not a string")

    # Validate values are integers, strings, or lists of integers and strings
    for key, value in session.items():
        if isinstance(value, (int, str)):
            continue
        elif isinstance(value, list):
            for item in value:
                if not isinstance(item, (int, str)):
                    raise ValueError(f"Session value for key {key!r} contains invalid item {item!r}")
        else:
            raise ValueError(f"Session value for key {key!r} has invalid type {type(value).__name__}")

    return session
