def matches_filter(expression: str, record: dict) -> bool:
    """
    Evaluate a filter expression against a record dictionary.

    Args:
        expression: A string containing a filter expression using keys from record as variables.
        record: A dictionary containing key-value pairs to use in the expression.

    Returns:
        True if the expression evaluates to True, False otherwise.

    Raises:
        ValueError: If the expression is invalid or uses a name not in record.
    """
    import ast
    import operator

    # Define allowed operators
    allowed_operators = {
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.And: lambda a, b: a and b,
        ast.Or: lambda a, b: a or b,
        ast.Not: lambda a: not a,
    }

    # Parse the expression
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        raise ValueError(f"Invalid expression: {expression}")

    # Evaluate the expression
    def evaluate(node):
        if isinstance(node, ast.Expression):
            return evaluate(node.body)
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            if node.id in record:
                return record[node.id]
            else:
                raise ValueError(f"Unknown variable: {node.id}")
        elif isinstance(node, ast.BinOp):
            left = evaluate(node.left)
            right = evaluate(node.right)
            op_type = type(node.op)
            if op_type not in allowed_operators:
                raise ValueError(f"Unsupported operator: {op_type.__name__}")
            return allowed_operators[op_type](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = evaluate(node.operand)
            op_type = type(node.op)
            if op_type not in allowed_operators:
                raise ValueError(f"Unsupported unary operator: {op_type.__name__}")
            return allowed_operators[op_type](operand)
        elif isinstance(node, ast.BoolOp):
            op_type = type(node.op)
            if op_type not in allowed_operators:
                raise ValueError(f"Unsupported boolean operator: {op_type.__name__}")
            values = [evaluate(v) for v in node.values]
            if op_type == ast.And:
                return all(values)
            elif op_type == ast.Or:
                return any(values)
        elif isinstance(node, ast.Compare):
            left = evaluate(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator)
                op_type = type(op)
                if op_type not in allowed_operators:
                    raise ValueError(f"Unsupported comparison operator: {op_type.__name__}")
                if not allowed_operators[op_type](left, right):
                    return False
                left = right
            return True
        else:
            raise ValueError(f"Unsupported expression element: {type(node).__name__}")

    result = evaluate(tree)
    return bool(result)
