import os


def hash_pin(pin: str) -> str:
    """
    Hash a numeric PIN (4-6 digits) and return a salted hash string.
    Raises ValueError if pin is not a valid PIN.
    """
    if not isinstance(pin, str):
        raise ValueError("PIN must be a string")
    if not (4 <= len(pin) <= 6):
        raise ValueError("PIN must be 4 to 6 digits")
    if not pin.isdigit():
        raise ValueError("PIN must contain only digits")

    # Generate a random salt
    salt = os.urandom(16)
    # Use PBKDF2 with SHA-256
    hashed = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    # Return salt and hash as hex string
    return salt.hex() + ':' + hashed.hex()


def check_pin(pin: str, stored: str) -> bool:
    """
    Check if a PIN matches a stored hash.
    Returns True if pin matches stored, False otherwise.
    """
    if not isinstance(pin, str):
        return False
    if not (4 <= len(pin) <= 6):
        return False
    if not pin.isdigit():
        return False
    if not isinstance(stored, str):
        return False

    try:
        parts = stored.split(':')
        if len(parts) != 2:
            return False
        salt_hex, hash_hex = parts
        salt = bytes.fromhex(salt_hex)
        expected_hash = bytes.fromhex(hash_hex)
    except (ValueError, TypeError):
        return False

    # Compute the hash with the same parameters
    computed_hash = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)

    # Use constant-time comparison
    return hmac.compare_digest(computed_hash, expected_hash)

